// Instalador: crea todas las carpetas y archivos del proyecto en la carpeta actual.
// Uso:  node instalar.js   (luego: npm install && npm start)
const fs = require('fs');
const path = require('path');
const archivos = {
 "README.md": "# Reserva de Espacios Acad\u00e9micos\n\nAplicaci\u00f3n web del Caso 2 de Programaci\u00f3n Aplicada. Permite reservar salas de estudio y laboratorios y **evita que dos reservas se crucen** en el mismo espacio y fecha. Incluye registro e inicio de sesi\u00f3n con perfiles de alumno, docente y directivo.\n\n## Tecnolog\u00eda\n- Node.js + Express (servidor y API JSON).\n- HTML, CSS y JavaScript puro (interfaz en `public/`).\n- Datos en arreglos de JavaScript en memoria (sin base de datos).\n- Pruebas con el ejecutor nativo de Node (`node --test`), sin dependencias extra.\n\n## Cuenta de demostraci\u00f3n\n| Perfil | Correo | Contrase\u00f1a |\n| --- | --- | --- |\n| Directivo | `directivo@institucion.edu` | `Admin123!` |\n\nAlumnos y docentes crean su cuenta desde **Crear cuenta**. Nadie puede registrarse como directivo.\n\n## Ejecutar\n```bash\nnpm install\nnpm start      # http://localhost:3000\nnpm test       # 14 pruebas autom\u00e1ticas\n```\nEn StackBlitz consulta **GUIA_STACKBLITZ.md** (paso a paso). El servidor usa `process.env.PORT` si existe y, si no, el puerto 3000.\n\n## Rutas principales\nTodas devuelven JSON y, salvo las p\u00fablicas, exigen `Authorization: Bearer <token>`.\n\n| M\u00e9todo | Ruta | Uso |\n| --- | --- | --- |\n| POST | `/usuarios/registro`, `/usuarios/login` | P\u00fablicas. Devuelven `token`. |\n| POST | `/usuarios/logout` \u00b7 GET `/usuarios/perfil` | Cerrar sesi\u00f3n \u00b7 perfil actual. |\n| GET | `/usuarios` | Lista de perfiles (solo directivo). |\n| GET | `/reservas` | Lista (filtros `espacio`, `solicitante`, `estado`, `fecha`). |\n| GET | `/reservas/:id` | Consulta una reserva. |\n| POST | `/reservas` | Crea una reserva (409 si hay cruce). |\n| PUT | `/reservas/:id` | Edita una reserva activa y futura. |\n| DELETE | `/reservas/:id` | Cancela (queda en el historial). |\n| GET | `/reservas/disponibilidad?espacio=1&fecha=AAAA-MM-DD` | Reservas activas del espacio ese d\u00eda. |\n| GET | `/reservas/espacio/:espacioId` | Reservas de un espacio. |\n| GET | `/reservas/solicitante/:solicitante` | Reservas de un solicitante. |\n| GET/POST/PUT | `/espacios`, `/espacios/:id` | Consultar (todos) \u00b7 crear/editar (directivo). |\n| GET | `/api/estado` | Comprueba que el servidor responde (p\u00fablica). |\n\n## Ejemplo: crear una reserva\n```json\nPOST /reservas\n{ \"espacio\": 1, \"fecha\": \"2026-12-01\", \"horaInicio\": \"08:00\", \"horaFin\": \"10:00\", \"motivo\": \"Trabajo grupal\" }\n```\nEl solicitante se toma de la sesi\u00f3n. Si hay cruce, la respuesta es HTTP `409` con el horario en conflicto.\n\n## Documentos del proyecto\n`requisitos.md` \u00b7 `planeacion.md` \u00b7 `dise\u00f1o.md` \u00b7 `pruebas.md` \u00b7 `GUIA_STACKBLITZ.md` \u00b7 `GUIA_EXPLICATIVA_DEL_PROYECTO.md`\n\n## L\u00edmites\n- Los datos (reservas, cuentas y sesiones) se pierden al reiniciar el servidor; es una decisi\u00f3n del alcance acad\u00e9mico.\n- Antes de un uso real: base de datos, cambiar la contrase\u00f1a del directivo, HTTPS y l\u00edmite de intentos de login.\n",
 "dise\u00f1o.md": "# Dise\u00f1o \u2014 Reserva de espacios acad\u00e9micos\n\n## 1. Arquitectura b\u00e1sica\n```\nNavegador (public/) \u2192 Ruta (routes) \u2192 [Middleware auth] \u2192 Controlador (controllers) \u2192 Datos (data) \u2192 Respuesta JSON\n```\nLa ruta recibe la petici\u00f3n; el middleware comprueba la sesi\u00f3n; el controlador valida y aplica las reglas; el m\u00f3dulo de datos lee o modifica la memoria; el controlador responde en JSON.\n\n## 2. Estructura de carpetas\n```\n/Reserva_Espacios_Academicos\n\u251c\u2500\u2500 index.js                  Servidor Express (arranque y conexi\u00f3n de rutas)\n\u251c\u2500\u2500 package.json\n\u251c\u2500\u2500 .stackblitzrc             Configuraci\u00f3n para StackBlitz\n\u251c\u2500\u2500 src\n\u2502   \u251c\u2500\u2500 routes\n\u2502   \u2502   \u251c\u2500\u2500 reservas.js\n\u2502   \u2502   \u251c\u2500\u2500 espacios.js\n\u2502   \u2502   \u2514\u2500\u2500 usuarios.js\n\u2502   \u251c\u2500\u2500 controllers\n\u2502   \u2502   \u251c\u2500\u2500 reservasController.js\n\u2502   \u2502   \u251c\u2500\u2500 espaciosController.js\n\u2502   \u2502   \u2514\u2500\u2500 usuariosController.js\n\u2502   \u251c\u2500\u2500 middleware\n\u2502   \u2502   \u2514\u2500\u2500 auth.js           autenticar / soloDirectivo\n\u2502   \u251c\u2500\u2500 data\n\u2502   \u2502   \u251c\u2500\u2500 reservas.js\n\u2502   \u2502   \u251c\u2500\u2500 espacios.js\n\u2502   \u2502   \u2514\u2500\u2500 usuarios.js\n\u2502   \u2514\u2500\u2500 utils\n\u2502       \u2514\u2500\u2500 validaciones.js   fechas, horas y cruces\n\u251c\u2500\u2500 public                    Interfaz web (index.html, styles.css, app.js)\n\u251c\u2500\u2500 tests                     Pruebas autom\u00e1ticas (node --test)\n\u251c\u2500\u2500 requisitos.md \u00b7 planeacion.md \u00b7 dise\u00f1o.md \u00b7 pruebas.md \u00b7 README.md\n\u251c\u2500\u2500 GUIA_STACKBLITZ.md\n\u2514\u2500\u2500 GUIA_EXPLICATIVA_DEL_PROYECTO.md\n```\n\n## 3. Modelo de datos\n### Espacio\n| Campo | Tipo | Obligatorio | Descripci\u00f3n |\n| --- | --- | --- | --- |\n| id | N\u00famero | S\u00ed | Identificador \u00fanico. |\n| nombre | Texto | S\u00ed | Nombre del espacio (m\u00edn. 3 caracteres, no repetido). |\n| ubicacion | Texto | S\u00ed | Lugar donde se encuentra. |\n| capacidad | N\u00famero | S\u00ed | M\u00e1ximo de personas (entero \u2265 1). |\n\n### Reserva\n| Campo | Tipo | Obligatorio | Descripci\u00f3n |\n| --- | --- | --- | --- |\n| id | N\u00famero | S\u00ed | Identificador \u00fanico. |\n| espacio | N\u00famero | S\u00ed | ID del espacio reservado. |\n| solicitante | Texto | S\u00ed | Persona que reserva (se toma de la sesi\u00f3n). |\n| fecha | Texto AAAA-MM-DD | S\u00ed | Fecha de la reserva (no puede ser pasada). |\n| horaInicio | Texto HH:MM | S\u00ed | Hora de inicio (24 h). |\n| horaFin | Texto HH:MM | S\u00ed | Hora de fin, posterior a la de inicio. |\n| estado | Texto | S\u00ed | `activa`, `cancelada` o `finalizada`. |\n| motivo | Texto | No | Hasta 300 caracteres. |\n| usuarioId / perfilSolicitante | N\u00famero / Texto | Auto | Due\u00f1o de la reserva y su perfil. |\n| creadaEn / modificadaEn / canceladaEn | Fecha ISO | Auto | Trazabilidad. |\n\n### Usuario (extensi\u00f3n)\nid, nombre, correo (\u00fanico), rol (`alumno`, `docente`, `directivo`), salt y hash de contrase\u00f1a (nunca se devuelven).\n\n## 4. Rutas de la API\n| M\u00e9todo | Ruta | Funci\u00f3n | Acceso |\n| --- | --- | --- | --- |\n| GET | /reservas | Lista reservas (filtros: espacio, solicitante, estado, fecha) | Sesi\u00f3n |\n| GET | /reservas/:id | Consulta una reserva | Due\u00f1o o directivo |\n| POST | /reservas | Crea una reserva | Sesi\u00f3n |\n| PUT | /reservas/:id | Edita una reserva activa y futura | Due\u00f1o o directivo |\n| DELETE | /reservas/:id | Cancela una reserva (queda en el historial) | Due\u00f1o o directivo |\n| GET | /reservas/disponibilidad?espacio=&fecha= | Disponibilidad de un espacio en una fecha | Sesi\u00f3n |\n| GET | /reservas/espacio/:espacioId | Reservas de un espacio | Sesi\u00f3n |\n| GET | /reservas/solicitante/:solicitante | Reservas de un solicitante | Sesi\u00f3n |\n| GET | /espacios, /espacios/:id | Consulta espacios | Sesi\u00f3n |\n| POST, PUT | /espacios, /espacios/:id | Crea o edita espacios | Directivo |\n| POST | /usuarios/registro, /usuarios/login | Alta e inicio de sesi\u00f3n | P\u00fablico |\n| POST | /usuarios/logout \u00b7 GET /usuarios/perfil | Cerrar sesi\u00f3n \u00b7 ver perfil | Sesi\u00f3n |\n| GET | /usuarios | Lista de perfiles | Directivo |\n| GET | /api/estado | Comprobar que el servidor responde | P\u00fablico |\n\nLas rutas espec\u00edficas (`/disponibilidad`, `/espacio/\u2026`, `/solicitante/\u2026`) se declaran antes de `/:id` para que no se confundan con un ID.\n\n## 5. Regla de negocio principal: evitar cruces\nHay conflicto si: **mismo espacio + misma fecha + horaInicioNueva < horaFinExistente + horaFinNueva > horaInicioExistente** (solo se comparan reservas `activa`).\n\n| Reserva existente | Nueva reserva | Resultado |\n| --- | --- | --- |\n| 08:00\u201310:00 | 10:00\u201312:00 | Permitida |\n| 08:00\u201310:00 | 09:00\u201311:00 | Rechazada (409) |\n| 08:00\u201310:00 | 08:30\u201309:30 | Rechazada (409) |\n| 08:00\u201310:00 | 07:00\u201308:00 | Permitida |\n| 08:00\u201310:00 | 10:00\u201311:00 | Permitida |\n\nEstos cinco casos est\u00e1n automatizados en `tests/cruces.test.js`.\n\n## 6. Permisos por perfil\n| Acci\u00f3n | Alumno | Docente | Directivo |\n| --- | :---: | :---: | :---: |\n| Registrarse / iniciar sesi\u00f3n | \u2714 | \u2714 | \u2714 (cuenta de prueba) |\n| Consultar disponibilidad y espacios | \u2714 | \u2714 | \u2714 |\n| Crear reserva | \u2714 | \u2714 | \u2714 |\n| Ver, editar y cancelar sus reservas | \u2714 | \u2714 | \u2714 |\n| Ver, editar y cancelar reservas ajenas | \u2718 | \u2718 | \u2714 |\n| Crear / editar espacios | \u2718 | \u2718 | \u2714 |\n| Listar perfiles registrados | \u2718 | \u2718 | \u2714 |\n\n## 7. Interfaz\nUna sola p\u00e1gina (`public/index.html`) con pantalla de acceso (iniciar sesi\u00f3n / crear cuenta) y panel con men\u00fa lateral: Inicio, Nueva reserva, Reservas, Disponibilidad, y para directivos Espacios y Perfiles. Paleta azul institucional `#1E4FA3`, verde menta `#2BA37F`; estados con color (verde activa, rojo cancelada). Dise\u00f1o adaptable a pantallas peque\u00f1as.\n",
 "GUIA_EXPLICATIVA_DEL_PROYECTO.md": "# Gu\u00eda explicativa del c\u00f3digo \u2014 Reserva de Espacios Acad\u00e9micos\n\nEste documento explica para qu\u00e9 sirve cada archivo y cada bloque de c\u00f3digo del proyecto, en lenguaje sencillo.\n\n## 1. Idea general\n\nLa aplicaci\u00f3n tiene dos partes que se comunican:\n\n- **Backend (servidor):** Node.js + Express. Guarda los datos, valida las reglas y responde en JSON.\n- **Frontend (navegador):** `public/` con HTML, CSS y JavaScript. Muestra pantallas y llama a la API con `fetch`.\n\nCamino de una petici\u00f3n (arquitectura del documento del proyecto):\n\n```\nNavegador \u2192 Ruta \u2192 Middleware (\u00bfhay sesi\u00f3n?) \u2192 Controlador (validaciones y reglas) \u2192 Datos (memoria) \u2192 JSON\n```\n\n## 2. Estructura de carpetas\n\n| Carpeta o archivo | Para qu\u00e9 sirve |\n| --- | --- |\n| `index.js` | Arranca el servidor y conecta todo. |\n| `src/routes/` | Define las direcciones (URL) de la API. |\n| `src/controllers/` | Contiene la l\u00f3gica: validar, decidir y responder. |\n| `src/middleware/` | Filtros que se ejecutan antes del controlador (sesi\u00f3n y permisos). |\n| `src/data/` | \"Base de datos\" en memoria: guardar y buscar. |\n| `src/utils/` | Funciones auxiliares reutilizables (fechas, horas, cruces). |\n| `public/` | La p\u00e1gina web que ve el usuario. |\n| `tests/` | Pruebas autom\u00e1ticas. |\n| `package.json` / `.stackblitzrc` | Dependencias, scripts y configuraci\u00f3n de StackBlitz. |\n\n---\n\n## 3. Backend\n\n### 3.1 `index.js` \u2014 servidor principal\n\n| Bloque | Qu\u00e9 hace |\n| --- | --- |\n| `require('express')` y `path` | Carga Express (el framework) y `path` (para armar rutas de carpetas). |\n| `app.disable('x-powered-by')` | Oculta que el servidor usa Express (peque\u00f1a mejora de seguridad). |\n| `express.json({ limit: '100kb' })` | Permite leer cuerpos JSON y rechaza los demasiado grandes. |\n| `express.static('public')` | Entrega `index.html`, `styles.css` y `app.js` al navegador. |\n| `app.use('/usuarios', \u2026)` | Conecta registro, login y perfil. Estas rutas son p\u00fablicas, salvo las que protegen por dentro. |\n| `app.use('/reservas', autenticar, \u2026)` y `/espacios` | Conectan la API principal **detr\u00e1s** del middleware: sin sesi\u00f3n responden 401. |\n| `GET /api/estado` | Ruta p\u00fablica para comprobar que el servidor est\u00e1 vivo. |\n| Manejador 404 | Si la ruta no existe, responde JSON con \"Ruta no encontrada\". |\n| Manejador de errores | Si el JSON viene mal formado responde 400; cualquier otro fallo responde 500 sin mostrar detalles internos. |\n| `app.listen(PORT, '0.0.0.0')` | Enciende el servidor en el puerto de `PORT` (lo da StackBlitz) o en el 3000. Solo se ejecuta si el archivo se lanza directamente. |\n| `module.exports = app` | Permite que las pruebas importen la app sin encenderla. |\n\n### 3.2 `src/routes/` \u2014 rutas\n\n**`reservas.js`**\n\n| L\u00ednea | Qu\u00e9 hace |\n| --- | --- |\n| `GET /disponibilidad`, `/espacio/:espacioId`, `/solicitante/:solicitante` | Rutas espec\u00edficas. Van **antes** de `/:id`; si no, Express confundir\u00eda la palabra \"disponibilidad\" con un ID. |\n| `GET /` y `GET /:id` | Listar todas y consultar una (RF2, RF3). |\n| `POST /` | Crear reserva (RF1). |\n| `PUT /:id` | Editar reserva (RF4). |\n| `DELETE /:id` | Cancelar reserva (RF5). |\n\n**`espacios.js`** \u2014 `GET` es para cualquier usuario con sesi\u00f3n; `POST` y `PUT` pasan primero por `soloDirectivo(...)`.\n\n**`usuarios.js`** \u2014 `registro` y `login` sin protecci\u00f3n; `logout`, `perfil` con `autenticar`; el listado completo con `autenticar` + `soloDirectivo`.\n\n### 3.3 `src/middleware/auth.js` \u2014 sesi\u00f3n y permisos\n\n| Funci\u00f3n | Qu\u00e9 hace |\n| --- | --- |\n| `autenticar` | Lee el encabezado `Authorization: Bearer <token>`, busca la sesi\u00f3n y, si es v\u00e1lida, guarda el usuario en `req.user`. Si no, responde **401**. |\n| `soloDirectivo(mensaje)` | Devuelve un filtro que deja pasar solo al perfil directivo; a los dem\u00e1s les responde **403** con el mensaje indicado. |\n\n### 3.4 `src/controllers/reservasController.js` \u2014 l\u00f3gica de reservas\n\n| Funci\u00f3n | Qu\u00e9 hace |\n| --- | --- |\n| `actualizarEstadosFinalizados` | Antes de cada consulta, marca como `finalizada` las reservas activas cuya fecha y hora ya pasaron (hora de Bogot\u00e1). |\n| `listar` | Devuelve las reservas ordenadas por fecha y hora. El directivo ve todas; los dem\u00e1s solo las suyas. Aplica filtros `espacio`, `solicitante`, `estado` y `fecha`. |\n| `obtenerPorId` | Devuelve una reserva (404 si no existe, 403 si es de otra persona). |\n| `crear` | 1) toma el solicitante de la sesi\u00f3n, 2) valida los datos (400), 3) busca cruces (409), 4) guarda y responde 201. |\n| `editar` | Solo permite editar reservas **activas y futuras** del propio usuario (o cualquiera si es directivo). Vuelve a validar y a revisar cruces ignorando la misma reserva. |\n| `cancelar` | Cambia el estado a `cancelada` sin borrar el registro (queda el historial). |\n| `listarPorEspacio` / `listarPorSolicitante` | Implementan RF8 y RF9. |\n| `consultarDisponibilidad` | Recibe `espacio` y `fecha` y devuelve las reservas **activas** de ese d\u00eda y si el espacio est\u00e1 libre (RF7). |\n\n### 3.5 `src/controllers/espaciosController.js`\n\n| Funci\u00f3n | Qu\u00e9 hace |\n| --- | --- |\n| `validarEspacio` | Exige nombre (\u2265 3 caracteres), ubicaci\u00f3n y capacidad entera mayor que cero. |\n| `listar` / `obtenerPorId` | Consultan espacios. |\n| `crear` / `editar` | Validan, impiden nombres repetidos (409) y guardan. Solo los alcanza el directivo. |\n\n### 3.6 `src/controllers/usuariosController.js`\n\n| Funci\u00f3n | Qu\u00e9 hace |\n| --- | --- |\n| `ROLES_PERMITIDOS` | Solo `alumno` y `docente`: nadie puede registrarse como directivo. |\n| `registro` | Valida nombre, correo, contrase\u00f1a (\u2265 8 caracteres) y perfil; evita correos repetidos (409); crea la cuenta e inicia sesi\u00f3n. |\n| `login` | Verifica correo y contrase\u00f1a y entrega un token; el mismo mensaje sirve para \"correo malo\" y \"clave mala\" para no dar pistas. |\n| `logout` | Elimina el token de la sesi\u00f3n. |\n| `perfil` / `listar` | Devuelven el usuario actual / todos los usuarios (solo directivo). |\n\n### 3.7 `src/utils/validaciones.js` \u2014 reglas reutilizables\n\n| Funci\u00f3n | Qu\u00e9 hace |\n| --- | --- |\n| `fechaActualBogota` / `horaActualBogota` | Dan la fecha y hora de Colombia sin depender de la zona horaria del servidor. |\n| `esFechaISOValida` | Comprueba formato `AAAA-MM-DD` y que la fecha exista (rechaza 2026-02-30). |\n| `esHoraValida` | Comprueba formato `HH:MM` de 24 horas. |\n| `validarDatosReserva` | Verifica espacio existente, solicitante, fecha no pasada, horas v\u00e1lidas, fin posterior al inicio, hora de inicio no pasada si es hoy y motivo \u2264 300 caracteres (RF10). Devuelve el error o los datos limpios. |\n| `hayCruceHorario` | **Regla principal (RF6):** misma espacio + misma fecha + `inicioNuevo < finExistente` y `finNuevo > inicioExistente`. Ignora reservas no activas y, al editar, la propia reserva. |\n| `reservaEsFutura` | Dice si una reserva a\u00fan no ha empezado (para permitir editar o cancelar). |\n\n### 3.8 `src/data/` \u2014 datos en memoria\n\n| Archivo | Qu\u00e9 contiene |\n| --- | --- |\n| `espacios.js` | Arreglo con 3 espacios iniciales y funciones `listarEspacios`, `buscarEspacio`, `crearEspacio`, `actualizarEspacio`. |\n| `reservas.js` | Arreglo vac\u00edo y funciones `crearReserva` (asigna ID, estado `activa` y fechas), `actualizarReserva`, `cancelarReserva`, `buscarReserva`, `listarReservas`. |\n| `usuarios.js` | Cuentas y sesiones. Contrase\u00f1a guardada con **PBKDF2 + sal aleatoria** (nunca en texto visible); token de 64 caracteres aleatorios con **vigencia de 8 horas**; `vistaPublica` oculta hash y sal; crea el directivo de prueba al iniciar. |\n\nLos datos se pierden al reiniciar el servidor; as\u00ed lo pide el alcance (datos en memoria).\n\n---\n\n## 4. Frontend (`public/`)\n\n### 4.1 `index.html`\n\n| Bloque | Qu\u00e9 hace |\n| --- | --- |\n| `#auth-screen` | Pantalla de acceso con formularios de *iniciar sesi\u00f3n* y *crear cuenta*. |\n| `.sidebar` / `.main-nav` | Men\u00fa lateral. Los botones con `data-admin-only` solo los ve el directivo. |\n| `#view-dashboard` | Resumen: contadores y pr\u00f3ximas reservas. |\n| `#view-form` | Formulario de nueva reserva / edici\u00f3n. |\n| `#view-reservas` | Filtros, tabla de reservas y bot\u00f3n de exportar CSV. |\n| `#view-disponibilidad` | Consulta de disponibilidad por espacio y fecha. |\n| `#view-espacios` | Lista y formulario de espacios (directivo). |\n| `#view-perfiles` | Cuentas registradas (directivo). |\n| `<dialog id=\"reservation-dialog\">` | Ventana emergente con el detalle de una reserva. |\n\n### 4.2 `styles.css`\n\n| Bloque | Qu\u00e9 hace |\n| --- | --- |\n| `:root { --blue \u2026 }` | Variables de color y radio, para cambiar el estilo en un solo lugar. |\n| `.app-shell`, `.sidebar`, `.main-content` | Disposici\u00f3n de dos columnas: men\u00fa y contenido. |\n| `.button`, `.panel`, formularios | Estilo com\u00fan de botones, tarjetas y campos. |\n| Insignias de estado | Verde (activa), rojo (cancelada), gris (finalizada). |\n| `@media` | Adapta el dise\u00f1o a pantallas peque\u00f1as. |\n\n### 4.3 `app.js`\n\n| Bloque | Qu\u00e9 hace |\n| --- | --- |\n| `storage` | Guarda token y usuario en `localStorage` **con protecci\u00f3n**: si el navegador lo bloquea (pasa a veces en el iframe de StackBlitz) la app sigue funcionando. |\n| `state` | Objeto con el estado actual: espacios, reservas, vista, token y usuario. |\n| `escapeHtml` | Evita que texto escrito por usuarios se interprete como c\u00f3digo HTML. |\n| `formatDate`, `formatDateTime`, `localDateString` | Dan formato a las fechas. |\n| `api(url, options)` | Funci\u00f3n central: a\u00f1ade el token a cada petici\u00f3n, llama a `fetch`, y convierte errores del servidor en mensajes. |\n| `showToast`, `showFormMessage` | Avisos de \u00e9xito o error al usuario. |\n| `loadBaseData`, `populateSpaceSelects` | Cargan los espacios y llenan las listas desplegables. |\n| `switchView` | Cambia entre pantallas del men\u00fa. |\n| `renderDashboard` | Pinta el resumen del inicio. |\n| `loadReservationList`, `reservationRow` | Piden las reservas con los filtros y dibujan cada fila con sus acciones. |\n| `resetReservationForm`, `startEditingReservation` | Preparan el formulario para crear o editar. |\n| `openReservationDetail`, `cancelReservation` | Muestran el detalle y cancelan con confirmaci\u00f3n. |\n| `renderSpaces`, `editSpace`, `resetSpaceForm` | Gesti\u00f3n visual de espacios. |\n| `consultAvailability` | Llama a `/reservas/disponibilidad` y muestra ocupaci\u00f3n. |\n| `exportReservationsCsv` | Genera y descarga un CSV con las reservas filtradas. |\n| `registerEvents` | Conecta cada bot\u00f3n y formulario con su funci\u00f3n. |\n| `startApp` | Al abrir la p\u00e1gina: conecta eventos, maneja login/registro/logout y, si ya hab\u00eda sesi\u00f3n, la restaura consultando `/usuarios/perfil`. |\n\n---\n\n## 5. Pruebas (`tests/`)\n\n| Archivo | Qu\u00e9 prueba |\n| --- | --- |\n| `validaciones.test.js` | Fechas y horas v\u00e1lidas, cruces simples y edici\u00f3n ignorando la propia reserva. |\n| `cruces.test.js` | Los 5 casos de la tabla de cruces del documento del proyecto. |\n| `reservasController.test.js` | Flujo de reservas: crear, rechazar cruce, editar, disponibilidad y cancelar. |\n| `api.test.js` | Prueba real contra el servidor: 401 sin sesi\u00f3n, registro y login, permisos 403, cruce 409, cierre de sesi\u00f3n. |\n\nSe ejecutan con `npm test` (resultado esperado: 14 aprobadas).\n\n## 6. Configuraci\u00f3n\n\n| Archivo | Para qu\u00e9 sirve |\n| --- | --- |\n| `package.json` | Nombre, scripts (`start`, `test`), versi\u00f3n m\u00ednima de Node y dependencia `express`. |\n| `.stackblitzrc` | Le indica a StackBlitz que instale dependencias y ejecute `npm start` autom\u00e1ticamente. |\n| `.gitignore` | Evita subir `node_modules` y archivos locales a GitHub. |\n\n## 7. Qu\u00e9 se cambi\u00f3 respecto al ZIP original\n\n1. **Autenticaci\u00f3n sacada de `index.js`** a `middleware/auth.js` y `controllers/usuariosController.js`, para respetar la separaci\u00f3n rutas / controladores / datos (RNF5).\n2. **Contrase\u00f1as con PBKDF2** (m\u00e1s portable que `scrypt` en StackBlitz) y **sesiones que caducan a las 8 horas**.\n3. **El solicitante se toma de la sesi\u00f3n** en la API: antes la API exig\u00eda enviarlo en el cuerpo de la petici\u00f3n, lo que permit\u00eda escribir otro nombre; ahora un alumno o docente no puede reservar a nombre de otra persona.\n4. **Validaci\u00f3n extra:** no se puede reservar con hora de inicio ya pasada el mismo d\u00eda.\n5. **`localStorage` protegido** para que no falle en la vista previa de StackBlitz.\n6. **Configuraci\u00f3n StackBlitz:** `.stackblitzrc`, `engines` y servidor escuchando en `0.0.0.0`.\n7. **Documentos actualizados** (`README`, `requisitos`, `dise\u00f1o`, `pruebas`) que dec\u00edan que no hab\u00eda autenticaci\u00f3n; nuevo `planeacion.md` con backlog, sprints y Kanban.\n8. **Pruebas nuevas:** de 5 a 14 (cruces del documento y API completa).\n",
 ".gitignore": "node_modules/\n.env\n.DS_Store\nnpm-debug.log*\n",
 "planeacion.md": "# Planeaci\u00f3n \u00e1gil \u2014 Scrum simplificado\n\n## Roles (rotan entre los integrantes)\n| Rol | Responsabilidad |\n| --- | --- |\n| Product Owner | Vela por que lo construido responda a los requisitos y prioriza el trabajo. |\n| Scrum Master | Organiza las reuniones cortas y mantiene el tablero. |\n| Developer(s) | Desarrollan las funcionalidades y participan en los dem\u00e1s roles. |\n\n## Product Backlog\n| ID | Historia de usuario | Prioridad | Estado |\n| --- | --- | --- | --- |\n| HU01 | Como usuario, quiero crear una reserva para apartar un espacio acad\u00e9mico. | Alta | Hecha |\n| HU02 | Como usuario, quiero consultar las reservas existentes. | Alta | Hecha |\n| HU03 | Como usuario, quiero consultar una reserva por su ID. | Media | Hecha |\n| HU04 | Como usuario, quiero editar una reserva. | Alta | Hecha |\n| HU05 | Como usuario, quiero cancelar una reserva. | Alta | Hecha |\n| HU06 | Como usuario, quiero consultar la disponibilidad de un espacio en una fecha. | Alta | Hecha |\n| HU07 | Como sistema, quiero detectar cruces de horario. | Muy alta | Hecha |\n| HU08 | Como usuario, quiero filtrar reservas por espacio. | Media | Hecha |\n| HU09 | Como usuario, quiero filtrar reservas por solicitante. | Media | Hecha |\n| HU10 | Como persona de la instituci\u00f3n, quiero registrarme e iniciar sesi\u00f3n (extensi\u00f3n). | Alta | Hecha |\n\n## Criterios de aceptaci\u00f3n principales\n| Historia | Criterio |\n| --- | --- |\n| HU01 | Con datos requeridos y sin conflicto, la reserva se crea (HTTP 201). |\n| HU02 | La API devuelve las reservas registradas. |\n| HU04 | Una reserva activa y futura se modifica sin generar informaci\u00f3n inconsistente. |\n| HU05 | Una reserva existente puede cancelarse. |\n| HU06 | La consulta indica las reservas existentes del espacio y fecha pedidos. |\n| HU07 | Una reserva que se cruce se rechaza con HTTP 409 y un mensaje claro. |\n\n## Sprints\n| Sprint | Objetivo | Actividades |\n| --- | --- | --- |\n| 1 \u2014 Semana 2 | Funcionalidades base | GET listar/consultar y POST crear; estructura inicial y datos en memoria. |\n| 2 \u2014 Semana 3 | Funcionalidades restantes | PUT, DELETE, validaci\u00f3n de cruces, disponibilidad y filtros. |\n| 3 \u2014 Semana 4 | Cierre | Ajustes, pruebas, documentaci\u00f3n y despliegue. |\n\n## Tablero Kanban\nColumnas: **Por hacer \u00b7 En progreso \u00b7 Hecho.** Una historia pasa a *Hecho* solo si el c\u00f3digo funciona, est\u00e1 subido a GitHub y otro integrante lo prob\u00f3 manualmente.\n\n## Check-in y revisi\u00f3n\nAl iniciar cada sesi\u00f3n: \u00bfqu\u00e9 hice?, \u00bfqu\u00e9 voy a hacer?, \u00bftengo alg\u00fan bloqueo? Al final de cada sprint se revisan las historias realmente terminadas y se ajusta el backlog.\n",
 ".stackblitzrc": "{\n  \"installDependencies\": true,\n  \"startCommand\": \"npm start\"\n}\n",
 "index.js": "const express = require('express');\nconst path = require('path');\n\nconst app = express();\n\napp.disable('x-powered-by');\napp.use(express.json({ limit: '100kb' }));\napp.use(express.static(path.join(__dirname, 'public')));\n\nconst { autenticar } = require('./src/middleware/auth');\n\n// Usuarios: registro y login son p\u00fablicos; el resto se protege dentro de la ruta.\napp.use('/usuarios', require('./src/routes/usuarios'));\n\n// API principal del Caso 2: exige sesi\u00f3n iniciada.\napp.use('/reservas', autenticar, require('./src/routes/reservas'));\napp.use('/espacios', autenticar, require('./src/routes/espacios'));\n\napp.get('/api/estado', (req, res) => {\n  res.json({\n    ok: true,\n    aplicacion: 'Reserva de espacios acad\u00e9micos',\n    almacenamiento: 'memoria',\n    mensaje: 'Los datos se reinician al reiniciar el servidor.'\n  });\n});\n\n// Respuesta JSON para rutas que no existen.\napp.use((req, res) => {\n  res.status(404).json({\n    ok: false,\n    error: 'Ruta no encontrada.',\n    ruta: req.originalUrl\n  });\n});\n\n// Manejo de JSON mal formado y otros errores inesperados.\napp.use((err, req, res, next) => {\n  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {\n    return res.status(400).json({\n      ok: false,\n      error: 'El cuerpo de la solicitud contiene JSON inv\u00e1lido.'\n    });\n  }\n\n  console.error(err);\n  return res.status(500).json({\n    ok: false,\n    error: 'Ocurri\u00f3 un error interno en el servidor.'\n  });\n});\n\nconst PORT = process.env.PORT || 3000;\n\nif (require.main === module) {\n  app.listen(PORT, '0.0.0.0', () => {\n    console.log(`Reserva de espacios activa en el puerto ${PORT}`);\n  });\n}\n\nmodule.exports = app;\n",
 "package.json": "{\n  \"name\": \"reserva-espacios-academicos\",\n  \"version\": \"1.1.0\",\n  \"private\": true,\n  \"description\": \"Aplicaci\u00f3n web para reservar salas de estudio y laboratorios sin cruces de horario (Express + datos en memoria).\",\n  \"main\": \"index.js\",\n  \"scripts\": {\n    \"start\": \"node index.js\",\n    \"test\": \"node --test\"\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"dependencies\": {\n    \"express\": \"^4.18.2\"\n  }\n}\n",
 "GUIA_STACKBLITZ.md": "# C\u00f3mo subir y ejecutar el proyecto en StackBlitz (paso a paso)\n\nStackBlitz ejecuta Node.js dentro del navegador, as\u00ed que no instalas nada en tu computador. Este proyecto ya incluye `package.json`, `.stackblitzrc` y el script `npm start`.\n\n> Importante: StackBlitz **no acepta el .zip directamente**. Primero hay que descomprimirlo.\n\n## Antes de empezar\n1. Descomprime `Reserva_Espacios_Academicos.zip` en tu computador.\n2. Verifica que dentro de la carpeta veas `index.js`, `package.json`, `src/` y `public/`.\n3. Si existe una carpeta `node_modules`, **no la subas** (StackBlitz la crea sola).\n4. Recomendado: usa **Google Chrome** o **Edge**. Safari y Brave pueden bloquear la vista previa.\n\n## Opci\u00f3n A \u2014 Arrastrar los archivos (la m\u00e1s r\u00e1pida)\n1. Entra a **https://stackblitz.com** e inicia sesi\u00f3n (con GitHub o correo). Sin cuenta puedes probar, pero no podr\u00e1s guardar el proyecto.\n2. Pulsa **Create new project** (o **New project**) y elige la plantilla **Node.js**.\n3. En el explorador de archivos (columna izquierda) borra los archivos de ejemplo que trae la plantilla (por ejemplo `index.js` y `package.json`).\n4. Abre la carpeta del proyecto en tu computador, selecciona **todo su contenido** (`index.js`, `package.json`, `.stackblitzrc`, `src`, `public`, `tests`, los `.md`\u2026) y **arr\u00e1stralo** al explorador de archivos de StackBlitz. Si pregunta si reemplazar archivos, responde que s\u00ed.\n5. Comprueba que en el explorador queden `src/` y `public/` como carpetas, no archivos sueltos.\n6. StackBlitz instala Express y arranca solo. Si no lo hace, abre la **Terminal** (parte inferior) y escribe:\n   ```bash\n   npm install\n   npm start\n   ```\n7. Debe aparecer `Reserva de espacios activa en el puerto ...` y se abre la **vista previa** a la derecha.\n8. Para verla mejor, pulsa **Open in New Tab** (abrir en pesta\u00f1a nueva).\n\n## Opci\u00f3n B \u2014 Mediante GitHub (tambi\u00e9n lo pide el proyecto)\nEl documento del proyecto exige que el c\u00f3digo est\u00e9 en GitHub, as\u00ed que esta ruta sirve para ambos fines.\n1. Crea un repositorio en **github.com** (por ejemplo `reserva-espacios-academicos`).\n2. Pulsa **Add file \u2192 Upload files**, arrastra el contenido de la carpeta (sin `node_modules`) y haz **Commit changes**.\n3. En el navegador abre:\n   ```\n   https://stackblitz.com/github/TU_USUARIO/reserva-espacios-academicos\n   ```\n   (cambia `TU_USUARIO` y el nombre del repositorio por los tuyos).\n4. StackBlitz importa el repositorio, instala las dependencias y lo ejecuta.\n\n## Probar que funciona\n1. En la vista previa debe verse la pantalla **Reserva de espacios acad\u00e9micos** con las pesta\u00f1as *Iniciar sesi\u00f3n* y *Crear cuenta*.\n2. Entra con `directivo@institucion.edu` y la contrase\u00f1a `Admin123!`.\n3. Crea una reserva y luego otra que se cruce de horario: debe mostrarse un error de conflicto.\n4. En la terminal puedes ejecutar `npm test` (en otra terminal si el servidor est\u00e1 corriendo) y deben aparecer **14 pruebas aprobadas**.\n\n## Guardar y compartir\n- Con la sesi\u00f3n iniciada, StackBlitz guarda los cambios en tu cuenta (bot\u00f3n **Save** / **Fork** si es necesario).\n- Para compartir, copia la URL de la barra del navegador, o usa el bot\u00f3n **Share**.\n- Para entregar solo la aplicaci\u00f3n funcionando, copia la URL de la vista previa en nueva pesta\u00f1a.\n\n## Problemas frecuentes\n| Problema | Soluci\u00f3n |\n| --- | --- |\n| `Cannot find module 'express'` | Ejecuta `npm install` en la terminal. |\n| La vista previa sale en blanco o no carga | Pulsa **Open in New Tab**; prueba en Chrome o Edge; desactiva el bloqueo de cookies de terceros para stackblitz.com. |\n| `Cannot GET /` | Falt\u00f3 la carpeta `public/` o qued\u00f3 con otro nombre. Revisa el paso 5. |\n| El puerto est\u00e1 ocupado | Det\u00e9n el proceso con `Ctrl + C` y ejecuta `npm start` de nuevo. |\n| Desaparecieron mis reservas y cuentas | Es normal: los datos est\u00e1n en memoria y se reinician con el servidor. |\n| Plantilla con otro `package.json` | Reempl\u00e1zalo por el de este proyecto (debe tener `\"start\": \"node index.js\"`). |\n| No me deja iniciar sesi\u00f3n tras reiniciar | Las cuentas de alumno/docente se borran al reiniciar; vuelve a crearlas. El directivo de prueba siempre existe. |\n",
 "requisitos.md": "# Requisitos \u2014 Reserva de espacios acad\u00e9micos\n\n## Objetivo\nDesarrollar una aplicaci\u00f3n web que permita gestionar reservas de espacios acad\u00e9micos (salas de estudio y laboratorios), consultar su disponibilidad y evitar la duplicidad de reservas cuando exista un cruce de horarios.\n\n## Actores\n- **Solicitante** (alumno o docente): registra y consulta sus reservas.\n- **Administrador o gestor** (perfil *directivo*): supervisa todas las reservas y gestiona los espacios.\n- **Sistema:** valida los datos y comprueba autom\u00e1ticamente los conflictos de horario.\n\n## Entidades principales\n| Entidad | Campos |\n| --- | --- |\n| Espacio | id, nombre, ubicacion, capacidad |\n| Reserva | id, espacio, solicitante, fecha, horaInicio, horaFin, estado (+ motivo, usuarioId) |\n| Usuario (extensi\u00f3n) | id, nombre, correo, rol, contrase\u00f1a cifrada |\n\n## Requisitos funcionales (del documento del proyecto)\n| ID | Requisito |\n| --- | --- |\n| RF1 | Crear una nueva reserva. |\n| RF2 | Listar las reservas existentes. |\n| RF3 | Consultar una reserva espec\u00edfica por su ID. |\n| RF4 | Editar una reserva existente. |\n| RF5 | Cancelar una reserva (se conserva en el historial con estado `cancelada`). |\n| RF6 | Validar que no exista otra reserva para el mismo espacio y fecha con horario que se cruce. |\n| RF7 | Consultar la disponibilidad de un espacio en una fecha. |\n| RF8 | Listar reservas por espacio. |\n| RF9 | Listar reservas por solicitante. |\n| RF10 | Validar campos obligatorios y coherencia de horarios. |\n\n## Requisitos funcionales adicionales (extensi\u00f3n con usuarios)\n| ID | Requisito |\n| --- | --- |\n| RF11 | Registrar cuentas de alumno o docente e iniciar / cerrar sesi\u00f3n. |\n| RF12 | Un alumno o docente solo ve, edita y cancela **sus propias** reservas. |\n| RF13 | El directivo ve y gestiona todas las reservas, crea y edita espacios y consulta los perfiles registrados. |\n\n## Requisitos no funcionales\n- **RNF1:** la API responde en formato JSON.\n- **RNF2:** los campos obligatorios se validan antes de guardar.\n- **RNF3:** la aplicaci\u00f3n es accesible desde un navegador web.\n- **RNF4:** se usan c\u00f3digos HTTP adecuados (200, 201, 400, 401, 403, 404, 409, 500).\n- **RNF5:** el c\u00f3digo est\u00e1 organizado en rutas, controladores y archivos de datos (m\u00e1s `middleware` y `utils`).\n\n## Alcance\nLos datos se guardan en arreglos de JavaScript en memoria (sin base de datos) y se reinician al reiniciar el servidor. Es un prototipo acad\u00e9mico: antes de uso real se requiere base de datos, cambiar la contrase\u00f1a del directivo de prueba y usar HTTPS.\n",
 "pruebas.md": "# Pruebas \u2014 Reserva de espacios acad\u00e9micos\n\n## Pruebas autom\u00e1ticas\nEjecuta `npm test`. Resultado esperado: **14 pruebas aprobadas**, que cubren validaci\u00f3n de fechas y horas, los cinco casos de cruce del documento, el flujo completo de la API (registro, login, permisos 401/403, crear, cruce 409, editar, cancelar, disponibilidad) y el cierre de sesi\u00f3n.\n\n## Pruebas manuales en la interfaz\nAntes: `npm install` y `npm start` (en StackBlitz se hace solo).\n\n| # | Paso | Resultado esperado |\n| --- | --- | --- |\n| 1 | Entra con `directivo@institucion.edu` / `Admin123!` | Se abre el panel con las opciones Espacios y Perfiles. |\n| 2 | Cierra sesi\u00f3n y usa **Crear cuenta** como alumno | Entra directo al panel; no ve Espacios ni Perfiles. |\n| 3 | **Nueva reserva**: espacio 1, fecha futura, 08:00\u201310:00 | Mensaje de \u00e9xito; aparece en **Reservas** como *Activa*. |\n| 4 | Crea otra en el mismo espacio y fecha, 09:00\u201311:00 | Error de conflicto (HTTP 409) indicando el horario ocupado. |\n| 5 | Crea otra de 10:00\u201312:00 | Se permite (empieza cuando termina la anterior). |\n| 6 | Intenta hora fin 13:00 con hora inicio 14:00 | Error de validaci\u00f3n. |\n| 7 | **Disponibilidad**: espacio 1 y la fecha usada | Lista las reservas activas de ese d\u00eda. |\n| 8 | Edita una reserva futura | Los cambios se reflejan. |\n| 9 | Cancela una reserva | Queda como *Cancelada* y sigue en el historial. |\n| 10 | Entra con otra cuenta de alumno | No ve las reservas de la primera cuenta. |\n| 11 | Como directivo, abre **Reservas** | Ve las de todos; puede editar o cancelar cualquiera. |\n| 12 | **Reservas \u2192 Exportar CSV** | Se descarga el listado. |\n| 13 | Reinicia el servidor | Se borran reservas y cuentas (datos en memoria). |\n\n## Pruebas de la API (ejemplos con token)\n1. `POST /usuarios/login` con el directivo \u2192 devuelve `token`.\n2. `GET /reservas` con `Authorization: Bearer <token>` \u2192 200. Sin token \u2192 401.\n3. `POST /reservas` con `{\"espacio\":1,\"fecha\":\"AAAA-MM-DD\",\"horaInicio\":\"08:00\",\"horaFin\":\"10:00\"}` \u2192 201.\n\n## Registro de resultados\nMarca solo lo que hayas ejecutado realmente en tu entorno.\n",
 "src/controllers/espaciosController.js": "const espaciosData = require('../data/espacios');\n\nfunction validarEspacio(body) {\n  if (!body || typeof body !== 'object' || Array.isArray(body)) {\n    return { error: 'Env\u00eda los datos del espacio en formato JSON.' };\n  }\n\n  const nombre = typeof body.nombre === 'string' ? body.nombre.trim() : '';\n  const ubicacion = typeof body.ubicacion === 'string' ? body.ubicacion.trim() : '';\n  const capacidad = Number(body.capacidad);\n\n  if (nombre.length < 3) return { error: 'El nombre debe tener al menos 3 caracteres.' };\n  if (ubicacion.length < 2) return { error: 'La ubicaci\u00f3n es obligatoria.' };\n  if (!Number.isInteger(capacidad) || capacidad < 1) return { error: 'La capacidad debe ser un n\u00famero entero mayor que cero.' };\n\n  return { datos: { nombre, ubicacion, capacidad } };\n}\n\nfunction listar(req, res) {\n  return res.json(espaciosData.listarEspacios());\n}\n\nfunction obtenerPorId(req, res) {\n  const espacio = espaciosData.buscarEspacio(req.params.id);\n  if (!espacio) return res.status(404).json({ ok: false, error: 'No se encontr\u00f3 el espacio solicitado.' });\n  return res.json(espacio);\n}\n\nfunction crear(req, res) {\n  const validacion = validarEspacio(req.body);\n  if (validacion.error) return res.status(400).json({ ok: false, error: validacion.error });\n\n  const repetido = espaciosData.listarEspacios().some((item) => item.nombre.toLocaleLowerCase('es-CO') === validacion.datos.nombre.toLocaleLowerCase('es-CO'));\n  if (repetido) return res.status(409).json({ ok: false, error: 'Ya existe un espacio con ese nombre.' });\n\n  const espacio = espaciosData.crearEspacio(validacion.datos);\n  return res.status(201).json({ ok: true, mensaje: 'Espacio creado correctamente.', espacio });\n}\n\nfunction editar(req, res) {\n  const existente = espaciosData.buscarEspacio(req.params.id);\n  if (!existente) return res.status(404).json({ ok: false, error: 'No se encontr\u00f3 el espacio solicitado.' });\n\n  const validacion = validarEspacio({ ...existente, ...req.body });\n  if (validacion.error) return res.status(400).json({ ok: false, error: validacion.error });\n\n  const repetido = espaciosData.listarEspacios().some((item) => item.id !== existente.id && item.nombre.toLocaleLowerCase('es-CO') === validacion.datos.nombre.toLocaleLowerCase('es-CO'));\n  if (repetido) return res.status(409).json({ ok: false, error: 'Ya existe otro espacio con ese nombre.' });\n\n  const espacio = espaciosData.actualizarEspacio(existente.id, validacion.datos);\n  return res.json({ ok: true, mensaje: 'Espacio actualizado correctamente.', espacio });\n}\n\nmodule.exports = { listar, obtenerPorId, crear, editar };\n",
 "src/controllers/usuariosController.js": "const usuariosData = require('../data/usuarios');\n\n// El perfil \"directivo\" no se puede elegir al registrarse.\nconst ROLES_PERMITIDOS = ['alumno', 'docente'];\n\nfunction registro(req, res) {\n  const { nombre, correo, password, rol } = req.body || {};\n  if (typeof nombre !== 'string' || nombre.trim().length < 3) {\n    return res.status(400).json({ ok: false, error: 'Escribe tu nombre completo (m\u00ednimo 3 caracteres).' });\n  }\n  if (typeof correo !== 'string' || !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(correo)) {\n    return res.status(400).json({ ok: false, error: 'Escribe un correo v\u00e1lido.' });\n  }\n  if (typeof password !== 'string' || password.length < 8) {\n    return res.status(400).json({ ok: false, error: 'La contrase\u00f1a debe tener al menos 8 caracteres.' });\n  }\n  if (!ROLES_PERMITIDOS.includes(rol)) {\n    return res.status(400).json({ ok: false, error: 'Selecciona el perfil alumno o docente.' });\n  }\n  if (usuariosData.buscarPorCorreo(correo)) {\n    return res.status(409).json({ ok: false, error: 'Ya existe una cuenta con ese correo.' });\n  }\n\n  const usuario = usuariosData.crearUsuario({ nombre, correo, password, rol });\n  const token = usuariosData.crearSesion(usuario);\n  return res.status(201).json({\n    ok: true,\n    token,\n    usuario: usuariosData.vistaPublica(usuario),\n    mensaje: 'Cuenta creada correctamente.'\n  });\n}\n\nfunction login(req, res) {\n  const { correo, password } = req.body || {};\n  const usuario = usuariosData.buscarPorCorreo(correo);\n  if (!usuariosData.verificarPassword(usuario, String(password || ''))) {\n    return res.status(401).json({ ok: false, error: 'Correo o contrase\u00f1a incorrectos.' });\n  }\n  return res.json({\n    ok: true,\n    token: usuariosData.crearSesion(usuario),\n    usuario: usuariosData.vistaPublica(usuario),\n    mensaje: 'Inicio de sesi\u00f3n correcto.'\n  });\n}\n\nfunction logout(req, res) {\n  usuariosData.cerrarSesion(req.sessionToken);\n  return res.json({ ok: true, mensaje: 'Sesi\u00f3n cerrada.' });\n}\n\nfunction perfil(req, res) {\n  return res.json(req.user);\n}\n\nfunction listar(req, res) {\n  return res.json(usuariosData.listarUsuarios());\n}\n\nmodule.exports = { registro, login, logout, perfil, listar };\n",
 "src/controllers/reservasController.js": "const espaciosData = require('../data/espacios');\nconst reservasData = require('../data/reservas');\nconst {\n  fechaActualBogota,\n  horaActualBogota,\n  esFechaISOValida,\n  validarDatosReserva,\n  hayCruceHorario,\n  reservaEsFutura\n} = require('../utils/validaciones');\n\nfunction actualizarEstadosFinalizados() {\n  const hoy = fechaActualBogota();\n  const hora = horaActualBogota();\n  reservasData.listarReservas().forEach((reserva) => {\n    if (reserva.estado === 'activa') {\n      const yaPaso = reserva.fecha < hoy || (reserva.fecha === hoy && reserva.horaFin <= hora);\n      if (yaPaso) reserva.estado = 'finalizada';\n    }\n  });\n}\n\nfunction listar(req, res) {\n  actualizarEstadosFinalizados();\n  let resultado = [...reservasData.listarReservas()];\n  if (req.user && req.user.rol !== 'directivo') resultado = resultado.filter(r => r.usuarioId === req.user.id);\n  const { espacio, espacioId, solicitante, estado, fecha } = req.query;\n  const filtroEspacio = espacio ?? espacioId;\n\n  if (filtroEspacio) resultado = resultado.filter((r) => r.espacio === Number(filtroEspacio));\n  if (solicitante) {\n    const termino = String(solicitante).toLocaleLowerCase('es-CO');\n    resultado = resultado.filter((r) => r.solicitante.toLocaleLowerCase('es-CO').includes(termino));\n  }\n  if (estado) resultado = resultado.filter((r) => r.estado === estado);\n  if (fecha) resultado = resultado.filter((r) => r.fecha === fecha);\n\n  resultado.sort((a, b) => `${a.fecha}T${a.horaInicio}`.localeCompare(`${b.fecha}T${b.horaInicio}`));\n  return res.json(resultado);\n}\n\nfunction obtenerPorId(req, res) {\n  actualizarEstadosFinalizados();\n  const reserva = reservasData.buscarReserva(req.params.id);\n  if (!reserva) return res.status(404).json({ ok: false, error: 'No se encontr\u00f3 la reserva solicitada.' });\n  if (req.user && req.user.rol !== 'directivo' && reserva.usuarioId !== req.user.id) return res.status(403).json({ ok: false, error: 'Solo puedes consultar tus propias reservas.' });\n  return res.json(reserva);\n}\n\nfunction crear(req, res) {\n  actualizarEstadosFinalizados();\n  // El solicitante sale de la sesi\u00f3n: un alumno/docente no puede reservar a nombre de otra persona.\n  // Solo el directivo puede indicar otro nombre (si no lo env\u00eda, se usa el suyo).\n  const cuerpo = { ...(req.body || {}) };\n  if (req.user && (req.user.rol !== 'directivo' || !cuerpo.solicitante)) cuerpo.solicitante = req.user.nombre;\n\n  const validacion = validarDatosReserva(cuerpo, espaciosData.listarEspacios());\n  if (validacion.error) return res.status(400).json({ ok: false, error: validacion.error });\n\n  const conflicto = hayCruceHorario(validacion.datos, reservasData.listarReservas());\n  if (conflicto) {\n    return res.status(409).json({\n      ok: false,\n      error: `El espacio ya est\u00e1 reservado de ${conflicto.horaInicio} a ${conflicto.horaFin} en esa fecha. Elige otro horario u otro espacio.`,\n      conflicto\n    });\n  }\n\n  const datosReserva = req.user ? { ...validacion.datos, usuarioId: req.user.id, perfilSolicitante: req.user.rol } : validacion.datos;\n  const reserva = reservasData.crearReserva(datosReserva);\n  return res.status(201).json({ ok: true, mensaje: 'Reserva creada correctamente.', reserva });\n}\n\nfunction editar(req, res) {\n  actualizarEstadosFinalizados();\n  const existente = reservasData.buscarReserva(req.params.id);\n  if (!existente) return res.status(404).json({ ok: false, error: 'No se encontr\u00f3 la reserva solicitada.' });\n  if (req.user && req.user.rol !== 'directivo' && existente.usuarioId !== req.user.id) return res.status(403).json({ ok: false, error: 'Solo puedes editar tus propias reservas.' });\n  if (existente.estado !== 'activa' || !reservaEsFutura(existente)) {\n    return res.status(409).json({ ok: false, error: 'Solo se pueden editar reservas activas y futuras.' });\n  }\n\n  const cuerpoEdicion = req.user && req.user.rol !== 'directivo' ? { ...req.body, solicitante: req.user.nombre } : { ...existente, ...req.body };\n  const validacion = validarDatosReserva({ ...existente, ...cuerpoEdicion }, espaciosData.listarEspacios());\n  if (validacion.error) return res.status(400).json({ ok: false, error: validacion.error });\n\n  const conflicto = hayCruceHorario(validacion.datos, reservasData.listarReservas(), existente.id);\n  if (conflicto) {\n    return res.status(409).json({\n      ok: false,\n      error: `El nuevo horario se cruza con una reserva de ${conflicto.horaInicio} a ${conflicto.horaFin}.`,\n      conflicto\n    });\n  }\n\n  const actualizada = reservasData.actualizarReserva(existente.id, validacion.datos);\n  return res.json({ ok: true, mensaje: 'Reserva actualizada correctamente.', reserva: actualizada });\n}\n\nfunction cancelar(req, res) {\n  actualizarEstadosFinalizados();\n  const existente = reservasData.buscarReserva(req.params.id);\n  if (!existente) return res.status(404).json({ ok: false, error: 'No se encontr\u00f3 la reserva solicitada.' });\n  if (req.user && req.user.rol !== 'directivo' && existente.usuarioId !== req.user.id) return res.status(403).json({ ok: false, error: 'Solo puedes cancelar tus propias reservas.' });\n  if (existente.estado !== 'activa' || !reservaEsFutura(existente)) {\n    return res.status(409).json({ ok: false, error: 'Solo se pueden cancelar reservas activas y futuras.' });\n  }\n\n  const cancelada = reservasData.cancelarReserva(existente.id);\n  return res.json({ ok: true, mensaje: 'Reserva cancelada. Se conserv\u00f3 en el historial.', reserva: cancelada });\n}\n\nfunction listarPorEspacio(req, res) {\n  actualizarEstadosFinalizados();\n  const espacioId = Number(req.params.espacioId);\n  if (!espaciosData.buscarEspacio(espacioId)) {\n    return res.status(404).json({ ok: false, error: 'El espacio indicado no existe.' });\n  }\n  let resultado = reservasData.listarReservas().filter((r) => r.espacio === espacioId);\n  if (req.user && req.user.rol !== 'directivo') resultado = resultado.filter(r => r.usuarioId === req.user.id);\n  return res.json(resultado);\n}\n\nfunction listarPorSolicitante(req, res) {\n  actualizarEstadosFinalizados();\n  const termino = String(req.params.solicitante).toLocaleLowerCase('es-CO');\n  let resultado = reservasData.listarReservas().filter((r) => r.solicitante.toLocaleLowerCase('es-CO').includes(termino));\n  if (req.user && req.user.rol !== 'directivo') resultado = resultado.filter(r => r.usuarioId === req.user.id);\n  return res.json(resultado);\n}\n\nfunction consultarDisponibilidad(req, res) {\n  actualizarEstadosFinalizados();\n  const espacioId = Number(req.query.espacio ?? req.query.espacioId);\n  const { fecha } = req.query;\n  if (!Number.isInteger(espacioId) || espacioId <= 0 || !fecha) {\n    return res.status(400).json({ ok: false, error: 'Debes enviar los par\u00e1metros espacio y fecha.' });\n  }\n  const espacio = espaciosData.buscarEspacio(espacioId);\n  if (!espacio) return res.status(404).json({ ok: false, error: 'El espacio indicado no existe.' });\n  if (!esFechaISOValida(fecha)) return res.status(400).json({ ok: false, error: 'La fecha no es v\u00e1lida; usa AAAA-MM-DD.' });\n\n  const reservas = reservasData.listarReservas()\n    .filter((r) => r.espacio === espacioId && r.fecha === fecha && r.estado === 'activa')\n    .sort((a, b) => a.horaInicio.localeCompare(b.horaInicio));\n\n  return res.json({\n    espacio,\n    fecha,\n    disponible: reservas.length === 0,\n    totalReservasActivas: reservas.length,\n    reservas: reservas.map(({ id, solicitante, horaInicio, horaFin, motivo, estado }) => ({\n      id, solicitante, horaInicio, horaFin, motivo, estado\n    }))\n  });\n}\n\nmodule.exports = {\n  listar,\n  obtenerPorId,\n  crear,\n  editar,\n  cancelar,\n  listarPorEspacio,\n  listarPorSolicitante,\n  consultarDisponibilidad\n};\n",
 "src/middleware/auth.js": "// Middleware de autenticaci\u00f3n y autorizaci\u00f3n.\n// Se ejecuta ANTES de los controladores de las rutas protegidas.\nconst usuariosData = require('../data/usuarios');\n\n// Lee el token \"Bearer\" del encabezado Authorization y carga el usuario en req.user.\nfunction autenticar(req, res, next) {\n  const authorization = req.headers.authorization || '';\n  const token = authorization.startsWith('Bearer ') ? authorization.slice(7) : '';\n  const usuario = usuariosData.usuarioPorToken(token);\n  if (!usuario) {\n    return res.status(401).json({ ok: false, error: 'Debes iniciar sesi\u00f3n para continuar.' });\n  }\n  req.user = usuariosData.vistaPublica(usuario);\n  req.sessionToken = token;\n  return next();\n}\n\n// F\u00e1brica de middleware: deja pasar solo a usuarios con perfil \"directivo\".\nfunction soloDirectivo(mensaje = 'Esta acci\u00f3n es solo para directivos.') {\n  return (req, res, next) => {\n    if (req.user && req.user.rol === 'directivo') return next();\n    return res.status(403).json({ ok: false, error: mensaje });\n  };\n}\n\nmodule.exports = { autenticar, soloDirectivo };\n",
 "src/data/usuarios.js": "// Usuarios y sesiones en memoria: prototipo acad\u00e9mico, no producci\u00f3n.\n// Se usa PBKDF2 (m\u00f3dulo crypto de Node) porque funciona igual en StackBlitz y en un servidor normal.\nconst crypto = require('crypto');\n\nconst ITERACIONES = 100000;\nconst LONGITUD_HASH = 64;\nconst ALGORITMO = 'sha512';\nconst DURACION_SESION_MS = 8 * 60 * 60 * 1000; // 8 horas\n\nconst usuarios = [];\nconst sesiones = new Map(); // token -> { usuarioId, expira }\nlet siguienteId = 1;\n\nfunction calcularHash(password, salt) {\n  return crypto.pbkdf2Sync(password, salt, ITERACIONES, LONGITUD_HASH, ALGORITMO);\n}\n\nfunction hashPassword(password, salt = crypto.randomBytes(16).toString('hex')) {\n  return { salt, hash: calcularHash(password, salt).toString('hex') };\n}\n\nfunction crearUsuario({ nombre, correo, password, rol }) {\n  const credenciales = hashPassword(password);\n  const usuario = {\n    id: siguienteId++,\n    nombre: nombre.trim(),\n    correo: correo.trim().toLowerCase(),\n    rol,\n    ...credenciales\n  };\n  usuarios.push(usuario);\n  return usuario;\n}\n\nfunction buscarPorCorreo(correo) {\n  const buscado = String(correo || '').trim().toLowerCase();\n  return usuarios.find((u) => u.correo === buscado);\n}\n\nfunction verificarPassword(usuario, password) {\n  if (!usuario) return false;\n  const intento = calcularHash(password, usuario.salt);\n  return crypto.timingSafeEqual(intento, Buffer.from(usuario.hash, 'hex'));\n}\n\n// Nunca se devuelven el hash ni la sal.\nfunction vistaPublica(u) {\n  return { id: u.id, nombre: u.nombre, correo: u.correo, rol: u.rol };\n}\n\nfunction crearSesion(usuario) {\n  const token = crypto.randomBytes(32).toString('hex');\n  sesiones.set(token, { usuarioId: usuario.id, expira: Date.now() + DURACION_SESION_MS });\n  return token;\n}\n\nfunction usuarioPorToken(token) {\n  const sesion = sesiones.get(token);\n  if (!sesion) return null;\n  if (sesion.expira < Date.now()) {\n    sesiones.delete(token);\n    return null;\n  }\n  return usuarios.find((u) => u.id === sesion.usuarioId) || null;\n}\n\nfunction cerrarSesion(token) {\n  sesiones.delete(token);\n}\n\nfunction listarUsuarios() {\n  return usuarios.map(vistaPublica);\n}\n\n// Cuenta inicial de directivo para pruebas. Cambiar credenciales en cualquier despliegue real.\ncrearUsuario({\n  nombre: 'Directivo de prueba',\n  correo: 'directivo@institucion.edu',\n  password: 'Admin123!',\n  rol: 'directivo'\n});\n\nmodule.exports = {\n  crearUsuario,\n  buscarPorCorreo,\n  verificarPassword,\n  vistaPublica,\n  crearSesion,\n  usuarioPorToken,\n  cerrarSesion,\n  listarUsuarios\n};\n",
 "src/data/espacios.js": "// Datos temporales en memoria. No se utiliza una base de datos.\nconst espacios = [\n  { id: 1, nombre: 'Sala de estudio 1', ubicacion: 'Bloque A', capacidad: 6 },\n  { id: 2, nombre: 'Sala de estudio 3', ubicacion: 'Bloque B', capacidad: 8 },\n  { id: 3, nombre: 'Laboratorio de sistemas', ubicacion: 'Bloque C', capacidad: 30 }\n];\n\nlet siguienteId = 4;\n\nfunction listarEspacios() {\n  return espacios;\n}\n\nfunction buscarEspacio(id) {\n  return espacios.find((espacio) => espacio.id === Number(id));\n}\n\nfunction crearEspacio(datos) {\n  const nuevo = { id: siguienteId++, ...datos };\n  espacios.push(nuevo);\n  return nuevo;\n}\n\nfunction actualizarEspacio(id, datos) {\n  const espacio = buscarEspacio(id);\n  if (!espacio) return null;\n  Object.assign(espacio, datos);\n  return espacio;\n}\n\nmodule.exports = {\n  listarEspacios,\n  buscarEspacio,\n  crearEspacio,\n  actualizarEspacio\n};\n",
 "src/data/reservas.js": "// La lista comienza vac\u00eda y vive \u00fanicamente mientras el servidor est\u00e1 encendido.\nconst reservas = [];\nlet siguienteId = 1;\n\nfunction listarReservas() {\n  return reservas;\n}\n\nfunction buscarReserva(id) {\n  return reservas.find((reserva) => reserva.id === Number(id));\n}\n\nfunction crearReserva(datos) {\n  const nueva = {\n    id: siguienteId++,\n    ...datos,\n    usuarioId: datos.usuarioId ?? null,\n    perfilSolicitante: datos.perfilSolicitante ?? null,\n    estado: 'activa',\n    creadaEn: new Date().toISOString(),\n    canceladaEn: null,\n    modificadaEn: null\n  };\n  reservas.push(nueva);\n  return nueva;\n}\n\nfunction actualizarReserva(id, datos) {\n  const reserva = buscarReserva(id);\n  if (!reserva) return null;\n  Object.assign(reserva, datos, { modificadaEn: new Date().toISOString() });\n  return reserva;\n}\n\nfunction cancelarReserva(id) {\n  const reserva = buscarReserva(id);\n  if (!reserva) return null;\n  reserva.estado = 'cancelada';\n  reserva.canceladaEn = new Date().toISOString();\n  return reserva;\n}\n\nmodule.exports = {\n  listarReservas,\n  buscarReserva,\n  crearReserva,\n  actualizarReserva,\n  cancelarReserva\n};\n",
 "src/utils/validaciones.js": "function obtenerPartesFechaBogota() {\n  const partes = new Intl.DateTimeFormat('en-CA', {\n    timeZone: 'America/Bogota',\n    year: 'numeric',\n    month: '2-digit',\n    day: '2-digit'\n  }).formatToParts(new Date());\n  return Object.fromEntries(partes.filter((parte) => parte.type !== 'literal').map((parte) => [parte.type, parte.value]));\n}\n\nfunction fechaActualBogota() {\n  const p = obtenerPartesFechaBogota();\n  return `${p.year}-${p.month}-${p.day}`;\n}\n\nfunction horaActualBogota() {\n  const p = new Intl.DateTimeFormat('en-GB', {\n    timeZone: 'America/Bogota',\n    hour: '2-digit',\n    minute: '2-digit',\n    hourCycle: 'h23'\n  }).formatToParts(new Date());\n  const valores = Object.fromEntries(p.filter((parte) => parte.type !== 'literal').map((parte) => [parte.type, parte.value]));\n  return `${valores.hour}:${valores.minute}`;\n}\n\nfunction esFechaISOValida(fecha) {\n  if (typeof fecha !== 'string' || !/^\\d{4}-\\d{2}-\\d{2}$/.test(fecha)) return false;\n  const [anio, mes, dia] = fecha.split('-').map(Number);\n  const comprobacion = new Date(Date.UTC(anio, mes - 1, dia));\n  return comprobacion.getUTCFullYear() === anio\n    && comprobacion.getUTCMonth() === mes - 1\n    && comprobacion.getUTCDate() === dia;\n}\n\nfunction esHoraValida(hora) {\n  return typeof hora === 'string' && /^([01]\\d|2[0-3]):[0-5]\\d$/.test(hora);\n}\n\nfunction validarDatosReserva(datos, espacios) {\n  if (!datos || typeof datos !== 'object' || Array.isArray(datos)) {\n    return { error: 'Env\u00eda los datos de la reserva en formato JSON.' };\n  }\n\n  const espacioId = Number(datos.espacio ?? datos.espacioId);\n  if (!Number.isInteger(espacioId) || espacioId <= 0) {\n    return { error: 'Debes seleccionar un espacio v\u00e1lido.' };\n  }\n  const espacio = espacios.find((item) => item.id === espacioId);\n  if (!espacio) return { error: 'El espacio seleccionado no existe.' };\n\n  const solicitante = typeof datos.solicitante === 'string' ? datos.solicitante.trim() : '';\n  if (solicitante.length < 3) {\n    return { error: 'El nombre del solicitante debe tener al menos 3 caracteres.' };\n  }\n\n  const fecha = datos.fecha;\n  if (!esFechaISOValida(fecha)) {\n    return { error: 'La fecha debe ser v\u00e1lida y usar el formato AAAA-MM-DD.' };\n  }\n  if (fecha < fechaActualBogota()) {\n    return { error: 'No se permiten reservas en fechas pasadas.' };\n  }\n\n  const horaInicio = datos.horaInicio;\n  const horaFin = datos.horaFin;\n  if (!esHoraValida(horaInicio) || !esHoraValida(horaFin)) {\n    return { error: 'Las horas deben usar el formato HH:MM de 24 horas.' };\n  }\n  if (horaFin <= horaInicio) {\n    return { error: 'La hora de fin debe ser posterior a la hora de inicio.' };\n  }\n  if (fecha === fechaActualBogota() && horaInicio <= horaActualBogota()) {\n    return { error: 'La hora de inicio ya pas\u00f3; elige una hora posterior a la actual.' };\n  }\n\n  const motivo = typeof datos.motivo === 'string' ? datos.motivo.trim() : '';\n  if (motivo.length > 300) {\n    return { error: 'El motivo no puede superar los 300 caracteres.' };\n  }\n\n  return {\n    datos: {\n      espacio: espacioId,\n      solicitante,\n      fecha,\n      horaInicio,\n      horaFin,\n      motivo\n    }\n  };\n}\n\nfunction hayCruceHorario(nuevaReserva, reservas, idIgnorado = null) {\n  return reservas.find((existente) => {\n    if (existente.id === Number(idIgnorado)) return false;\n    if (existente.estado !== 'activa') return false;\n    if (existente.espacio !== Number(nuevaReserva.espacio)) return false;\n    if (existente.fecha !== nuevaReserva.fecha) return false;\n\n    // Dos reservas se cruzan si sus intervalos se superponen.\n    return nuevaReserva.horaInicio < existente.horaFin\n      && nuevaReserva.horaFin > existente.horaInicio;\n  }) || null;\n}\n\nfunction reservaEsFutura(reserva) {\n  const hoy = fechaActualBogota();\n  if (reserva.fecha > hoy) return true;\n  if (reserva.fecha < hoy) return false;\n  return reserva.horaInicio > horaActualBogota();\n}\n\nmodule.exports = {\n  fechaActualBogota,\n  horaActualBogota,\n  esFechaISOValida,\n  esHoraValida,\n  validarDatosReserva,\n  hayCruceHorario,\n  reservaEsFutura\n};\n",
 "src/routes/usuarios.js": "const express = require('express');\nconst controller = require('../controllers/usuariosController');\nconst { autenticar, soloDirectivo } = require('../middleware/auth');\n\nconst router = express.Router();\n\n// Rutas p\u00fablicas: no requieren sesi\u00f3n.\nrouter.post('/registro', controller.registro);\nrouter.post('/login', controller.login);\n\n// Rutas protegidas.\nrouter.post('/logout', autenticar, controller.logout);\nrouter.get('/perfil', autenticar, controller.perfil);\nrouter.get('/', autenticar, soloDirectivo('Solo los directivos pueden consultar todos los perfiles.'), controller.listar);\n\nmodule.exports = router;\n",
 "src/routes/espacios.js": "const express = require('express');\nconst controller = require('../controllers/espaciosController');\nconst { soloDirectivo } = require('../middleware/auth');\n\nconst router = express.Router();\n\n// Todos los usuarios con sesi\u00f3n pueden consultar espacios (autenticar se aplica en index.js).\nrouter.get('/', controller.listar);\nrouter.get('/:id', controller.obtenerPorId);\n\n// Solo el directivo crea o edita espacios.\nconst soloGestores = soloDirectivo('Solo los directivos pueden crear o editar espacios.');\nrouter.post('/', soloGestores, controller.crear);\nrouter.put('/:id', soloGestores, controller.editar);\n\nmodule.exports = router;\n",
 "src/routes/reservas.js": "const express = require('express');\nconst controller = require('../controllers/reservasController');\n\nconst router = express.Router();\n\n// Las rutas espec\u00edficas van antes de /:id para evitar confundir \"disponibilidad\" con un ID.\nrouter.get('/disponibilidad', controller.consultarDisponibilidad);\nrouter.get('/espacio/:espacioId', controller.listarPorEspacio);\nrouter.get('/solicitante/:solicitante', controller.listarPorSolicitante);\nrouter.get('/', controller.listar);\nrouter.get('/:id', controller.obtenerPorId);\nrouter.post('/', controller.crear);\nrouter.put('/:id', controller.editar);\nrouter.delete('/:id', controller.cancelar);\n\nmodule.exports = router;\n",
 "public/styles.css": ":root {\n  --blue: #1E4FA3;\n  --blue-dark: #173B7A;\n  --mint: #2BA37F;\n  --page: #F5F7FA;\n  --surface: #FFFFFF;\n  --ink: #1F2937;\n  --muted: #6B7280;\n  --border: #E3E8F0;\n  --green: #16A34A;\n  --amber: #F59E0B;\n  --red: #DC2626;\n  --radius: 12px;\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n  color: var(--ink);\n  background: var(--page);\n}\n\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--page); color: var(--ink); font-size: 14px; }\nbutton, input, select, textarea { font: inherit; }\nbutton { cursor: pointer; }\nbutton:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, a:focus-visible { outline: 3px solid #8CB6FF; outline-offset: 2px; }\n[hidden] { display: none !important; }\n\n.app-shell { min-height: 100vh; display: grid; grid-template-columns: 252px minmax(0, 1fr); }\n.sidebar { background: #fff; border-right: 1px solid var(--border); padding: 24px 16px 18px; display: flex; flex-direction: column; min-height: 100vh; }\n.brand { display: flex; align-items: center; gap: 11px; color: inherit; text-decoration: none; padding: 0 8px 28px; }\n.brand-mark { height: 42px; width: 42px; display: grid; place-items: center; flex: 0 0 42px; border-radius: 12px; background: var(--blue); color: white; font-size: 28px; font-weight: 700; }\n.brand strong, .brand small, .topbar-user strong, .topbar-user small { display: block; }\n.brand strong { font-size: 14px; letter-spacing: -.25px; }\n.brand small { color: var(--muted); font-size: 11px; margin-top: 4px; }\n.nav-label, .eyebrow { color: #7C8798; font-size: 10px; font-weight: 800; letter-spacing: 1.2px; }\n.nav-label { padding: 0 11px; margin-bottom: 10px; }\n.main-nav { display: grid; gap: 5px; }\n.nav-link { width: 100%; display: flex; align-items: center; gap: 13px; border: 0; background: transparent; color: #536174; padding: 12px 13px; text-align: left; border-radius: 8px; font-weight: 650; transition: background .15s ease, color .15s ease; }\n.nav-link span { width: 19px; display: inline-grid; place-items: center; font-size: 19px; line-height: 1; }\n.nav-link:hover { background: #F0F5FD; color: var(--blue); }\n.nav-link.active { background: #EAF1FC; color: var(--blue); }\n.sidebar-note { margin-top: auto; padding: 14px 12px; background: #F4F8FE; border: 1px solid #DDE9FC; border-radius: 10px; display: flex; align-items: flex-start; gap: 9px; }\n.note-icon { flex: 0 0 18px; height: 18px; display: grid; place-items: center; border-radius: 50%; background: #D6E5FF; color: var(--blue); font-size: 11px; font-weight: 800; }\n.sidebar-note p { margin: 0; color: #536174; font-size: 11px; line-height: 1.6; }\n.sidebar-note strong { display: inline-block; color: #23354E; margin-bottom: 2px; }\n.sidebar-footer { padding: 20px 7px 0; color: #8791A0; font-size: 10px; }\n\n.main-content { width: 100%; max-width: 1600px; padding: 28px clamp(18px, 3vw, 46px) 20px; margin: 0 auto; min-width: 0; }\n.topbar { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 29px; padding-bottom: 22px; border-bottom: 1px solid var(--border); }\n.topbar .eyebrow { margin: 0 0 7px; }\n.topbar h1 { margin: 0; font-size: clamp(24px, 2.4vw, 30px); letter-spacing: -.8px; font-weight: 760; }\n.topbar-user { display: flex; align-items: center; gap: 10px; min-width: max-content; }\n.user-avatar { height: 38px; width: 38px; border-radius: 50%; display: grid; place-items: center; background: #DCE9FC; color: var(--blue); font-weight: 800; }\n.topbar-user strong { font-size: 12px; }\n.topbar-user small { margin-top: 4px; font-size: 11px; color: var(--muted); }\n.view { animation: appear .18s ease-out; }\n@keyframes appear { from { opacity: .65; transform: translateY(3px); } to { opacity: 1; transform: translateY(0); } }\n.welcome-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 22px; }\nh2, h3, p { margin-top: 0; }\n.welcome-row h2, .section-intro h2 { font-size: 22px; letter-spacing: -.45px; margin: 0 0 6px; }\n.welcome-row p, .section-intro p, .panel-heading p { color: var(--muted); margin: 0; line-height: 1.6; }\n.button { display: inline-flex; justify-content: center; align-items: center; gap: 7px; border-radius: 8px; border: 1px solid transparent; padding: 11px 16px; font-weight: 700; font-size: 13px; white-space: nowrap; transition: background .15s ease, border-color .15s ease, transform .1s ease; }\n.button:active { transform: translateY(1px); }\n.button-primary { color: white; background: var(--blue); border-color: var(--blue); }\n.button-primary:hover { background: var(--blue-dark); border-color: var(--blue-dark); }\n.button-secondary { color: var(--blue); background: white; border-color: #C8D8F2; }\n.button-secondary:hover { background: #F1F6FF; }\n.button-danger { color: white; background: var(--red); border-color: var(--red); }\n.button-danger:hover { background: #B91C1C; }\n.button-small { padding: 8px 11px; font-size: 12px; }\n.button-link { border: 0; padding: 5px 6px; color: var(--blue); background: transparent; font-weight: 700; font-size: 12px; }\n.button-link:hover { text-decoration: underline; }\n\n.stats-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin-bottom: 22px; }\n.stat-card { border: 1px solid var(--border); background: var(--surface); border-radius: var(--radius); display: flex; align-items: center; gap: 14px; padding: 20px; min-width: 0; }\n.stat-icon { width: 44px; height: 44px; flex: 0 0 44px; border-radius: 12px; display: grid; place-items: center; font-weight: 800; font-size: 21px; }\n.stat-icon.blue { color: var(--blue); background: #E8F0FE; }\n.stat-icon.green { color: #13865F; background: #DFF7EC; }\n.stat-icon.amber { color: #9A6100; background: #FFF3D6; }\n.stat-card p { margin: 0 0 7px; color: var(--muted); font-size: 12px; font-weight: 600; }\n.stat-card strong { display: block; font-size: 29px; letter-spacing: -1px; line-height: 1; margin-bottom: 7px; }\n.stat-card small { color: #8993A2; font-size: 11px; }\n.panel { background: #fff; border: 1px solid var(--border); border-radius: var(--radius); margin-bottom: 20px; min-width: 0; overflow: hidden; }\n.panel-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 21px 22px; }\n.panel-heading h2 { margin: 0 0 5px; font-size: 16px; letter-spacing: -.2px; }\n.panel-heading p { font-size: 12px; }\n.table-wrap { width: 100%; overflow-x: auto; }\ntable { border-collapse: collapse; width: 100%; min-width: 660px; text-align: left; }\nth { padding: 12px 17px; background: #F8FAFD; color: #697586; font-size: 10px; font-weight: 800; text-transform: uppercase; letter-spacing: .65px; white-space: nowrap; border-top: 1px solid #EEF1F6; border-bottom: 1px solid #E8ECF2; }\ntd { padding: 14px 17px; border-bottom: 1px solid #EEF1F6; vertical-align: middle; font-size: 12px; }\ntbody tr:last-child td { border-bottom: 0; }\ntbody tr:hover td { background: #FBFCFE; }\n.empty-cell { text-align: center; padding: 32px 18px; color: #8490A0; line-height: 1.6; }\n.status { display: inline-flex; align-items: center; gap: 6px; padding: 5px 8px; font-size: 10px; font-weight: 800; border-radius: 99px; white-space: nowrap; }\n.status::before { content: \"\"; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }\n.status-activa { color: #15803D; background: #DCFCE7; }\n.status-finalizada { color: #687383; background: #EEF1F4; }\n.status-cancelada { color: #B91C1C; background: #FEE2E2; }\n.action-group { display: flex; align-items: center; gap: 2px; }\n.info-strip { border: 1px solid #DAE7FC; background: #F0F6FF; border-radius: 10px; padding: 16px 18px; display: flex; align-items: flex-start; gap: 12px; color: var(--blue); }\n.info-strip > span { font-size: 20px; line-height: 1.2; }\n.info-strip strong { font-size: 12px; }\n.info-strip p { margin: 5px 0 0; font-size: 12px; color: #536174; line-height: 1.65; }\n\n.section-intro { display: flex; align-items: center; gap: 14px; margin: 3px 0 23px; }\n.section-icon { height: 48px; width: 48px; flex: 0 0 48px; border-radius: 13px; background: #E8F0FE; color: var(--blue); display: grid; place-items: center; font-size: 23px; font-weight: 800; }\n.form-panel { padding: 24px; }\n.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 21px 22px; }\nlabel { display: flex; flex-direction: column; gap: 7px; color: #38465A; font-size: 12px; font-weight: 750; min-width: 0; }\n.required { color: var(--red); }\n.muted { font-weight: 500; color: var(--muted); }\ninput, select, textarea { width: 100%; min-width: 0; border: 1px solid #D7DEE9; border-radius: 8px; background: #fff; color: var(--ink); padding: 11px 12px; outline: none; }\ninput, select { height: 42px; }\ntextarea { resize: vertical; min-height: 84px; }\ninput::placeholder, textarea::placeholder { color: #A0A8B5; }\ninput:focus, select:focus, textarea:focus { border-color: #7DA3E8; box-shadow: 0 0 0 3px #E9F1FF; }\nlabel small { color: #7B8696; font-size: 10px; line-height: 1.45; font-weight: 500; }\n.full-width { grid-column: 1 / -1; }\n.field-pair { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.form-actions { display: flex; justify-content: flex-end; align-items: center; gap: 10px; margin-top: 23px; }\n.form-message { padding: 11px 13px; margin-top: 18px; border-radius: 8px; font-size: 12px; line-height: 1.55; }\n.form-message.error { color: #9F1239; background: #FFF1F2; border: 1px solid #FECDD3; }\n.form-message.success { color: #166534; background: #F0FDF4; border: 1px solid #BBF7D0; }\n.filter-panel { padding: 17px 20px; }\n.filter-grid { display: grid; grid-template-columns: 1.1fr 1.25fr 1fr 1fr auto; gap: 12px; align-items: end; }\n.filter-actions { display: flex; gap: 7px; }\n.availability-form { display: grid; grid-template-columns: minmax(200px, 1.3fr) minmax(170px, 1fr) auto; gap: 16px; align-items: end; padding: 22px; }\n.availability-result { padding: 22px; }\n.empty-state { min-height: 170px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }\n.empty-state > span { font-size: 35px; color: #A5B8D7; }\n.empty-state h3 { margin: 10px 0 6px; font-size: 15px; }\n.empty-state p { color: var(--muted); margin: 0; line-height: 1.6; font-size: 12px; }\n.availability-header { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding-bottom: 16px; border-bottom: 1px solid var(--border); margin-bottom: 17px; }\n.availability-header h3 { margin: 0 0 4px; font-size: 17px; }\n.availability-header p { margin: 0; color: var(--muted); font-size: 12px; }\n.availability-summary { display: inline-block; padding: 8px 10px; background: #E7F8EF; border-radius: 8px; color: #15803D; font-size: 11px; font-weight: 800; white-space: nowrap; }\n.availability-summary.busy { background: #FFF4D9; color: #8A5900; }\n.availability-list { display: grid; gap: 9px; }\n.availability-item { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 13px 14px; border: 1px solid var(--border); border-radius: 8px; }\n.availability-item strong { font-size: 12px; }\n.availability-item small { display: block; margin-top: 4px; color: var(--muted); font-size: 11px; }\n.availability-empty { padding: 18px; border: 1px dashed #A9DABF; border-radius: 8px; background: #F5FCF8; color: #166534; font-size: 12px; line-height: 1.6; }\n.two-column-layout { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(280px, .8fr); gap: 18px; align-items: start; }\n.space-list { display: grid; }\n.space-card { display: flex; gap: 12px; align-items: flex-start; padding: 17px 20px; border-top: 1px solid #EEF1F6; }\n.space-symbol { height: 42px; width: 42px; flex: 0 0 42px; display: grid; place-items: center; border-radius: 11px; background: #EFF5FF; color: var(--blue); font-size: 21px; }\n.space-info { flex: 1; min-width: 0; }\n.space-info strong { display: block; margin: 1px 0 5px; font-size: 13px; }\n.space-info small { display: block; color: var(--muted); font-size: 11px; line-height: 1.5; }\n.space-actions { align-self: center; }\n.space-form { display: grid; gap: 17px; padding: 0 22px 22px; }\n.warning-strip { border: 1px solid #F9DDA2; background: #FFFAEB; color: #7B5200; border-radius: 8px; padding: 13px 15px; font-size: 11px; line-height: 1.65; margin-top: 3px; }\n.main-footer { display: flex; justify-content: space-between; gap: 15px; margin-top: 30px; border-top: 1px solid var(--border); padding: 18px 0 0; color: #8B95A3; font-size: 10px; }\n.toast { padding: 13px 16px; border-radius: 9px; margin-bottom: 20px; border: 1px solid; font-size: 12px; line-height: 1.6; }\n.toast.success { color: #166534; background: #F0FDF4; border-color: #BBF7D0; }\n.toast.error { color: #9F1239; background: #FFF1F2; border-color: #FECDD3; }\n.detail-dialog { border: 0; padding: 24px; border-radius: 14px; width: min(500px, calc(100% - 30px)); max-width: 500px; box-shadow: 0 20px 70px #10234440; }\n.detail-dialog::backdrop { background: #111D2D80; }\n.dialog-header { display: flex; justify-content: space-between; align-items: flex-start; gap: 15px; padding-bottom: 17px; border-bottom: 1px solid var(--border); }\n.dialog-header .eyebrow { margin: 0 0 5px; }\n.dialog-header h2 { margin: 0; font-size: 21px; }\n.icon-button { border: 1px solid var(--border); color: #596579; background: #fff; border-radius: 8px; width: 34px; height: 34px; font-size: 22px; }\n.detail-content { display: grid; gap: 0; padding-top: 10px; }\n.detail-row { padding: 12px 0; border-bottom: 1px solid #EEF1F6; }\n.detail-row small { display: block; color: var(--muted); font-size: 10px; margin-bottom: 5px; }\n.detail-row strong { display: block; font-size: 13px; line-height: 1.5; overflow-wrap: anywhere; }\n\n@media (max-width: 1150px) {\n  .app-shell { grid-template-columns: 220px minmax(0, 1fr); }\n  .filter-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .filter-actions { grid-column: 1 / -1; }\n  .stats-grid { gap: 10px; }\n  .stat-card { padding: 15px; gap: 10px; }\n}\n@media (max-width: 760px) {\n  .app-shell { display: block; }\n  .sidebar { min-height: 0; padding: 13px 14px 11px; border-right: 0; border-bottom: 1px solid var(--border); }\n  .brand { padding: 0 3px 13px; }\n  .brand-mark { width: 36px; height: 36px; flex-basis: 36px; font-size: 23px; }\n  .nav-label, .sidebar-note, .sidebar-footer { display: none; }\n  .main-nav { display: flex; gap: 5px; overflow-x: auto; padding-bottom: 3px; }\n  .nav-link { width: auto; flex: 0 0 auto; padding: 9px 10px; font-size: 11px; gap: 6px; }\n  .nav-link span { font-size: 15px; }\n  .main-content { padding: 18px 14px 15px; }\n  .topbar { margin-bottom: 22px; padding-bottom: 16px; }\n  .topbar-user { display: none; }\n  .topbar h1 { font-size: 24px; }\n  .welcome-row { align-items: flex-start; flex-direction: column; }\n  .stats-grid { grid-template-columns: 1fr; gap: 10px; }\n  .stat-card { padding: 14px 16px; }\n  .stat-card strong { font-size: 25px; }\n  .panel-heading { padding: 17px 15px; }\n  .form-panel { padding: 17px 15px; }\n  .form-grid { grid-template-columns: 1fr; gap: 18px; }\n  .full-width { grid-column: auto; }\n  .availability-form { grid-template-columns: 1fr; padding: 16px; }\n  .two-column-layout { grid-template-columns: 1fr; }\n  .section-intro { gap: 10px; }\n  .section-icon { width: 41px; height: 41px; flex-basis: 41px; }\n  .section-intro h2 { font-size: 20px; }\n  .main-footer { flex-direction: column; gap: 6px; }\n}\n@media (max-width: 430px) {\n  .filter-grid { grid-template-columns: 1fr; }\n  .filter-actions { grid-column: auto; }\n  .field-pair { grid-template-columns: 1fr 1fr; }\n  .welcome-row .button { width: 100%; }\n  .panel-heading { align-items: flex-start; }\n  .availability-header { align-items: flex-start; flex-direction: column; }\n  .availability-item { align-items: flex-start; flex-direction: column; }\n}\n\n/* Acceso de usuarios y registro */\n.auth-screen { min-height: 100vh; display: grid; place-items: center; padding: 24px; background: linear-gradient(135deg, #edf4ff, #f7f9fc); }\n.auth-card { width: min(100%, 480px); padding: 32px; border-radius: 20px; background: #fff; box-shadow: 0 18px 60px rgba(25, 55, 100, .14); }\n.auth-card h1 { margin: 8px 0; font-size: clamp(1.6rem, 4vw, 2.2rem); }\n.auth-card > p { color: #667085; line-height: 1.5; }\n.auth-tabs { display: flex; gap: 10px; margin: 22px 0; }\n.auth-tabs .button { flex: 1; }\n.auth-form { display: grid; gap: 16px; }\n.auth-form label { display: grid; gap: 7px; font-weight: 600; }\n.auth-form input, .auth-form select { width: 100%; padding: 12px; border: 1px solid #d0d5dd; border-radius: 9px; font: inherit; }\n.auth-form small, .auth-demo small { color: #667085; font-weight: 400; }\n.auth-demo { margin-top: 22px; padding: 12px; border-radius: 10px; background: #f5f7fb; font-size: .9rem; }\n[hidden] { display: none !important; }\n",
 "public/app.js": "// StackBlitz muestra la app dentro de un iframe; algunos navegadores bloquean localStorage ah\u00ed.\n// Estas funciones evitan que la app se rompa si el almacenamiento no est\u00e1 disponible.\nconst storage = {\n  get(key) { try { return localStorage.getItem(key); } catch { return null; } },\n  set(key, value) { try { localStorage.setItem(key, value); } catch { /* sin almacenamiento */ } },\n  remove(key) { try { localStorage.removeItem(key); } catch { /* sin almacenamiento */ } }\n};\n\nfunction leerUsuarioGuardado() {\n  try { return JSON.parse(storage.get('reservaUser') || 'null'); } catch { return null; }\n}\n\nconst state = {\n  spaces: [],\n  reservations: [],\n  filteredReservations: [],\n  currentView: 'dashboard',\n  toastTimer: null,\n  token: storage.get('reservaToken') || '',\n  user: leerUsuarioGuardado()\n};\n\nconst $ = (selector) => document.querySelector(selector);\nconst $$ = (selector) => [...document.querySelectorAll(selector)];\n\nfunction escapeHtml(value) {\n  return String(value ?? '').replace(/[&<>\"']/g, (character) => ({\n    '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;'\n  })[character]);\n}\n\nfunction formatDate(value) {\n  if (!value) return '\u2014';\n  const [year, month, day] = value.split('-').map(Number);\n  return new Intl.DateTimeFormat('es-CO', { day: '2-digit', month: 'short', year: 'numeric' })\n    .format(new Date(year, month - 1, day));\n}\n\nfunction formatDateTime(value) {\n  if (!value) return '\u2014';\n  const date = new Date(value);\n  if (Number.isNaN(date.getTime())) return '\u2014';\n  return new Intl.DateTimeFormat('es-CO', { dateStyle: 'medium', timeStyle: 'short' }).format(date);\n}\n\nfunction localDateString(date = new Date()) {\n  const year = date.getFullYear();\n  const month = String(date.getMonth() + 1).padStart(2, '0');\n  const day = String(date.getDate()).padStart(2, '0');\n  return `${year}-${month}-${day}`;\n}\n\nfunction defaultFutureDate() {\n  const date = new Date();\n  date.setDate(date.getDate() + 1);\n  return localDateString(date);\n}\n\nasync function api(url, options = {}) {\n  const requestOptions = { ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(state.token ? { Authorization: `Bearer ${state.token}` } : {}), ...(options.headers || {}) } };\n  const response = await fetch(url, requestOptions);\n  let data;\n  try {\n    data = await response.json();\n  } catch {\n    throw new Error('El servidor devolvi\u00f3 una respuesta que no es JSON.');\n  }\n  if (!response.ok) throw new Error(data.error || `Error HTTP ${response.status}`);\n  return data;\n}\n\nfunction showToast(message, type = 'success') {\n  const toast = $('#toast');\n  toast.textContent = message;\n  toast.className = `toast ${type}`;\n  toast.hidden = false;\n  clearTimeout(state.toastTimer);\n  state.toastTimer = setTimeout(() => { toast.hidden = true; }, 5000);\n}\n\nfunction showFormMessage(selector, message, type = 'error') {\n  const box = $(selector);\n  box.textContent = message;\n  box.className = `form-message ${type}`;\n  box.hidden = false;\n}\n\nfunction clearFormMessage(selector) {\n  const box = $(selector);\n  box.hidden = true;\n  box.textContent = '';\n}\n\nfunction getSpaceName(id) {\n  return state.spaces.find((space) => space.id === Number(id))?.nombre || `Espacio #${id}`;\n}\n\nfunction statusLabel(status) {\n  const labels = { activa: 'Activa', cancelada: 'Cancelada', finalizada: 'Finalizada' };\n  return labels[status] || status || 'Sin estado';\n}\n\nfunction statusBadge(status) {\n  const safeStatus = ['activa', 'cancelada', 'finalizada'].includes(status) ? status : 'finalizada';\n  return `<span class=\"status status-${safeStatus}\">${statusLabel(safeStatus)}</span>`;\n}\n\nfunction isFutureReservation(reservation) {\n  if (reservation.fecha > localDateString()) return true;\n  if (reservation.fecha < localDateString()) return false;\n  return `${reservation.fecha}T${reservation.horaInicio}:00` > localDateTimeMinute();\n}\n\nfunction localDateTimeMinute() {\n  const date = new Date();\n  return `${localDateString(date)}T${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}:00`;\n}\n\nfunction populateSpaceSelects() {\n  const selects = ['#reservation-space', '#filter-space', '#availability-space'];\n  for (const selector of selects) {\n    const select = $(selector);\n    if (!select) continue;\n    const previous = select.value;\n    const allOption = selector === '#filter-space' ? '<option value=\"\">Todos los espacios</option>' : '<option value=\"\">Selecciona un espacio</option>';\n    select.innerHTML = allOption + state.spaces.map((space) =>\n      `<option value=\"${space.id}\">${escapeHtml(space.nombre)} \u2014 ${escapeHtml(space.ubicacion)}</option>`\n    ).join('');\n    if ([...select.options].some((option) => option.value === previous)) select.value = previous;\n  }\n}\n\nasync function loadBaseData() {\n  const [spaces, reservations] = await Promise.all([api('/espacios'), api('/reservas')]);\n  state.spaces = spaces;\n  state.reservations = reservations;\n  if (state.user?.rol === 'directivo') { const profiles = await api('/usuarios'); $('#profiles-body').innerHTML = profiles.map(u => `<tr><td>${u.id}</td><td>${escapeHtml(u.nombre)}</td><td>${escapeHtml(u.correo)}</td><td>${escapeHtml(u.rol)}</td></tr>`).join(''); }\n  populateSpaceSelects();\n  renderDashboard();\n  renderSpaces();\n  if (state.currentView === 'reservas') await loadReservationList();\n}\n\nfunction switchView(view) {\n  const allowedViews = ['dashboard', 'form', 'reservas', 'disponibilidad', 'espacios', 'perfiles'];\n  if (['espacios', 'perfiles'].includes(view) && state.user?.rol !== 'directivo') { showToast('Esta secci\u00f3n es exclusiva para directivos.', 'error'); return; }\n  if (!allowedViews.includes(view)) return;\n  state.currentView = view;\n  $$('.view').forEach((section) => { section.hidden = section.id !== `view-${view}`; });\n  $$('.nav-link').forEach((button) => button.classList.toggle('active', button.dataset.viewLink === view));\n  const titles = {\n    dashboard: 'Resumen general', form: 'Nueva reserva', reservas: 'Reservas registradas',\n    disponibilidad: 'Disponibilidad', espacios: 'Espacios acad\u00e9micos', perfiles: 'Perfiles registrados'\n  };\n  $('#page-title').textContent = titles[view];\n\n  if (view === 'reservas') loadReservationList().catch((error) => showToast(error.message, 'error'));\n  if (view === 'espacios') renderSpaces();\n  if (view === 'form' && !$('#reservation-id').value) resetReservationForm();\n}\n\nfunction renderDashboard() {\n  const active = state.reservations.filter((reservation) => reservation.estado === 'activa');\n  $('#stat-total').textContent = String(state.reservations.length);\n  $('#stat-active').textContent = String(active.length);\n  $('#stat-spaces').textContent = String(state.spaces.length);\n\n  const upcoming = active\n    .filter(isFutureReservation)\n    .sort((a, b) => `${a.fecha}T${a.horaInicio}`.localeCompare(`${b.fecha}T${b.horaInicio}`))\n    .slice(0, 5);\n  const tbody = $('#upcoming-body');\n  if (!upcoming.length) {\n    tbody.innerHTML = '<tr><td colspan=\"5\" class=\"empty-cell\">Todav\u00eda no hay pr\u00f3ximas reservas. Crea la primera con el bot\u00f3n \u201cCrear reserva\u201d.</td></tr>';\n    return;\n  }\n  tbody.innerHTML = upcoming.map((reservation) => `\n    <tr>\n      <td><strong>${escapeHtml(getSpaceName(reservation.espacio))}</strong></td>\n      <td>${escapeHtml(reservation.solicitante)}</td>\n      <td>${escapeHtml(formatDate(reservation.fecha))}</td>\n      <td>${escapeHtml(reservation.horaInicio)}\u2013${escapeHtml(reservation.horaFin)}</td>\n      <td>${statusBadge(reservation.estado)}</td>\n    </tr>`).join('');\n}\n\nfunction reservationRow(reservation, includeActions = true) {\n  const actionsAllowed = reservation.estado === 'activa' && isFutureReservation(reservation);\n  const actions = includeActions ? `\n    <div class=\"action-group\">\n      <button class=\"button-link\" type=\"button\" data-action=\"detail\" data-id=\"${reservation.id}\">Ver</button>\n      ${actionsAllowed ? `<button class=\"button-link\" type=\"button\" data-action=\"edit\" data-id=\"${reservation.id}\">Editar</button><button class=\"button-link\" type=\"button\" data-action=\"cancel\" data-id=\"${reservation.id}\">Cancelar</button>` : ''}\n    </div>` : '';\n  return `<tr>\n    <td>#${reservation.id}</td>\n    <td><strong>${escapeHtml(getSpaceName(reservation.espacio))}</strong></td>\n    <td>${escapeHtml(reservation.solicitante)}</td>\n    <td>${escapeHtml(formatDate(reservation.fecha))}</td>\n    <td>${escapeHtml(reservation.horaInicio)}\u2013${escapeHtml(reservation.horaFin)}</td>\n    <td>${statusBadge(reservation.estado)}</td>\n    ${includeActions ? `<td>${actions}</td>` : ''}\n  </tr>`;\n}\n\nasync function loadReservationList() {\n  const parameters = new URLSearchParams();\n  const space = $('#filter-space').value;\n  const requester = $('#filter-requester').value.trim();\n  const status = $('#filter-status').value;\n  const date = $('#filter-date').value;\n  if (space) parameters.set('espacio', space);\n  if (requester) parameters.set('solicitante', requester);\n  if (status) parameters.set('estado', status);\n  if (date) parameters.set('fecha', date);\n\n  const suffix = parameters.toString() ? `?${parameters.toString()}` : '';\n  const reservations = await api(`/reservas${suffix}`);\n  state.filteredReservations = reservations;\n  $('#reservation-count').textContent = `${reservations.length} ${reservations.length === 1 ? 'resultado' : 'resultados'}`;\n  const tbody = $('#reservations-body');\n  tbody.innerHTML = reservations.length\n    ? reservations.map((reservation) => reservationRow(reservation, true)).join('')\n    : '<tr><td colspan=\"7\" class=\"empty-cell\">No se encontraron reservas con esos filtros.</td></tr>';\n}\n\nfunction resetReservationForm() {\n  $('#reservation-form').reset();\n  $('#reservation-requester').value = state.user?.nombre || '';\n  $('#reservation-requester').readOnly = state.user?.rol !== 'directivo';\n  $('#reservation-id').value = '';\n  $('#reservation-date').min = localDateString();\n  $('#reservation-date').value = defaultFutureDate();\n  $('#reservation-form-title').textContent = 'Registrar una reserva';\n  $('#reservation-submit').textContent = 'Confirmar reserva';\n  $('#cancel-edit').hidden = true;\n  clearFormMessage('#reservation-form-message');\n}\n\nfunction startEditingReservation(reservation) {\n  $('#reservation-id').value = reservation.id;\n  $('#reservation-space').value = String(reservation.espacio);\n  $('#reservation-requester').value = reservation.solicitante;\n  $('#reservation-requester').readOnly = state.user?.rol !== 'directivo';\n  $('#reservation-date').min = localDateString();\n  $('#reservation-date').value = reservation.fecha;\n  $('#reservation-start').value = reservation.horaInicio;\n  $('#reservation-end').value = reservation.horaFin;\n  $('#reservation-reason').value = reservation.motivo || '';\n  $('#reservation-form-title').textContent = `Editar reserva #${reservation.id}`;\n  $('#reservation-submit').textContent = 'Guardar cambios';\n  $('#cancel-edit').hidden = false;\n  clearFormMessage('#reservation-form-message');\n  switchView('form');\n}\n\nfunction openReservationDetail(reservation) {\n  $('#dialog-title').textContent = `Reserva #${reservation.id}`;\n  const fields = [\n    ['Espacio', getSpaceName(reservation.espacio)],\n    ['Solicitante', reservation.solicitante],\n    ['Fecha', formatDate(reservation.fecha)],\n    ['Horario', `${reservation.horaInicio}\u2013${reservation.horaFin}`],\n    ['Estado', statusLabel(reservation.estado)],\n    ['Motivo', reservation.motivo || 'No se indic\u00f3 un motivo'],\n    ['Creada el', formatDateTime(reservation.creadaEn)],\n    ['Modificada el', reservation.modificadaEn ? formatDateTime(reservation.modificadaEn) : 'No registra modificaciones'],\n    ['Cancelada el', reservation.canceladaEn ? formatDateTime(reservation.canceladaEn) : 'No aplica']\n  ];\n  const content = $('#dialog-content');\n  content.replaceChildren();\n  fields.forEach(([label, value]) => {\n    const row = document.createElement('div');\n    row.className = 'detail-row';\n    const caption = document.createElement('small');\n    caption.textContent = label;\n    const text = document.createElement('strong');\n    text.textContent = value;\n    row.append(caption, text);\n    content.append(row);\n  });\n  const dialog = $('#reservation-dialog');\n  if (typeof dialog.showModal === 'function') dialog.showModal();\n  else dialog.setAttribute('open', '');\n}\n\nasync function cancelReservation(id) {\n  const reservation = state.reservations.find((item) => item.id === Number(id));\n  if (!reservation) return;\n  const question = `\u00bfCancelar la reserva #${reservation.id}?\\n${getSpaceName(reservation.espacio)} \u00b7 ${formatDate(reservation.fecha)}\\n${reservation.horaInicio}\u2013${reservation.horaFin}\\n\\nLa reserva permanecer\u00e1 en el historial.`;\n  if (!window.confirm(question)) return;\n  try {\n    const result = await api(`/reservas/${id}`, { method: 'DELETE' });\n    showToast(result.mensaje || 'Reserva cancelada.');\n    await loadBaseData();\n    if (state.currentView === 'reservas') await loadReservationList();\n  } catch (error) {\n    showToast(error.message, 'error');\n  }\n}\n\nfunction renderSpaces() {\n  const container = $('#spaces-list');\n  if (!state.spaces.length) {\n    container.innerHTML = '<div class=\"empty-cell\">No hay espacios registrados.</div>';\n    return;\n  }\n  container.innerHTML = state.spaces.map((space) => `\n    <article class=\"space-card\">\n      <div class=\"space-symbol\" aria-hidden=\"true\">\u2302</div>\n      <div class=\"space-info\"><strong>${escapeHtml(space.nombre)}</strong><small>${escapeHtml(space.ubicacion)}</small><small>Capacidad: ${space.capacidad} personas \u00b7 ID ${space.id}</small></div>\n      <div class=\"space-actions\"><button class=\"button button-secondary button-small\" type=\"button\" data-action=\"edit-space\" data-id=\"${space.id}\">Editar</button></div>\n    </article>`).join('');\n}\n\nfunction resetSpaceForm() {\n  $('#space-form').reset();\n  $('#space-id').value = '';\n  $('#space-form-title').textContent = 'Agregar espacio';\n  $('#space-submit').textContent = 'Guardar espacio';\n  $('#cancel-space-edit').hidden = true;\n  clearFormMessage('#space-form-message');\n}\n\nfunction editSpace(space) {\n  $('#space-id').value = space.id;\n  $('#space-name').value = space.nombre;\n  $('#space-location').value = space.ubicacion;\n  $('#space-capacity').value = space.capacidad;\n  $('#space-form-title').textContent = `Editar espacio #${space.id}`;\n  $('#space-submit').textContent = 'Guardar cambios';\n  $('#cancel-space-edit').hidden = false;\n  clearFormMessage('#space-form-message');\n  $('#space-name').focus();\n}\n\nasync function consultAvailability(event) {\n  event.preventDefault();\n  const space = $('#availability-space').value;\n  const date = $('#availability-date').value;\n  if (!space || !date) return;\n  const resultPanel = $('#availability-result');\n  resultPanel.innerHTML = '<div class=\"empty-state\"><span aria-hidden=\"true\">\u25f7</span><h3>Consultando\u2026</h3><p>Buscando las reservas registradas para esa fecha.</p></div>';\n  try {\n    const parameters = new URLSearchParams({ espacio: space, fecha: date });\n    const result = await api(`/reservas/disponibilidad?${parameters.toString()}`);\n    const stateText = result.disponible ? 'Sin reservas activas' : `${result.totalReservasActivas} ${result.totalReservasActivas === 1 ? 'reserva activa' : 'reservas activas'}`;\n    resultPanel.innerHTML = `\n      <div class=\"availability-header\"><div><h3>${escapeHtml(result.espacio.nombre)}</h3><p>${escapeHtml(result.espacio.ubicacion)} \u00b7 ${escapeHtml(formatDate(result.fecha))}</p></div><span class=\"availability-summary ${result.disponible ? '' : 'busy'}\">${escapeHtml(stateText)}</span></div>\n      ${result.disponible\n        ? '<div class=\"availability-empty\"><strong>El espacio no tiene reservas activas registradas para esa fecha.</strong><br>Puedes continuar al formulario y solicitar el horario que necesitas.</div>'\n        : `<div class=\"availability-list\">${result.reservas.map((reservation) => `<div class=\"availability-item\"><div><strong>${escapeHtml(reservation.horaInicio)}\u2013${escapeHtml(reservation.horaFin)}</strong><small>${escapeHtml(reservation.solicitante)} \u00b7 Reserva #${reservation.id}</small>${reservation.motivo ? `<small>Motivo: ${escapeHtml(reservation.motivo)}</small>` : ''}</div>${statusBadge(reservation.estado)}</div>`).join('')}</div>`}\n      <div class=\"form-actions\"><button class=\"button button-primary\" type=\"button\" id=\"reserve-this-space\">\uff0b Crear reserva en este espacio</button></div>`;\n    $('#reserve-this-space').addEventListener('click', () => {\n      switchView('form'); // Cambiar de vista primero, porque al abrir el formulario se reinician sus campos.\n      $('#reservation-space').value = String(result.espacio.id);\n      $('#reservation-date').value = result.fecha;\n    });\n  } catch (error) {\n    resultPanel.innerHTML = `<div class=\"form-message error\">${escapeHtml(error.message)}</div>`;\n  }\n}\n\nfunction exportReservationsCsv() {\n  const rows = state.filteredReservations;\n  if (!rows.length) {\n    showToast('No hay reservas para exportar con los filtros actuales.', 'error');\n    return;\n  }\n  const values = [\n    ['ID', 'Espacio', 'Ubicaci\u00f3n', 'Solicitante', 'Fecha', 'Hora inicio', 'Hora fin', 'Estado', 'Motivo'],\n    ...rows.map((reservation) => {\n      const space = state.spaces.find((item) => item.id === Number(reservation.espacio));\n      return [reservation.id, space?.nombre || '', space?.ubicacion || '', reservation.solicitante, reservation.fecha, reservation.horaInicio, reservation.horaFin, statusLabel(reservation.estado), reservation.motivo || ''];\n    })\n  ];\n  const csv = values.map((row) => row.map((value) => `\"${String(value ?? '').replace(/\"/g, '\"\"')}\"`).join(';')).join('\\r\\n');\n  const blob = new Blob(['\\uFEFF', csv], { type: 'text/csv;charset=utf-8;' });\n  const url = URL.createObjectURL(blob);\n  const link = document.createElement('a');\n  link.href = url;\n  link.download = `reservas-${localDateString()}.csv`;\n  document.body.append(link);\n  link.click();\n  link.remove();\n  URL.revokeObjectURL(url);\n}\n\nfunction registerEvents() {\n  $$('[data-view-link]').forEach((button) => button.addEventListener('click', () => switchView(button.dataset.viewLink)));\n  $$('[data-go]').forEach((button) => button.addEventListener('click', () => switchView(button.dataset.go)));\n\n  $('#reservation-form').addEventListener('submit', async (event) => {\n    event.preventDefault();\n    clearFormMessage('#reservation-form-message');\n    const id = $('#reservation-id').value;\n    const data = {\n      espacio: Number($('#reservation-space').value),\n      solicitante: state.user?.rol === 'directivo' ? $('#reservation-requester').value.trim() : state.user?.nombre,\n      fecha: $('#reservation-date').value,\n      horaInicio: $('#reservation-start').value,\n      horaFin: $('#reservation-end').value,\n      motivo: $('#reservation-reason').value.trim()\n    };\n    try {\n      const result = await api(id ? `/reservas/${id}` : '/reservas', {\n        method: id ? 'PUT' : 'POST', body: JSON.stringify(data)\n      });\n      showToast(result.mensaje || 'Operaci\u00f3n realizada correctamente.');\n      resetReservationForm();\n      await loadBaseData();\n      switchView('reservas');\n    } catch (error) {\n      showFormMessage('#reservation-form-message', error.message, 'error');\n    }\n  });\n\n  $('#cancel-edit').addEventListener('click', () => { resetReservationForm(); switchView('reservas'); });\n  $('#reservation-filter').addEventListener('submit', async (event) => {\n    event.preventDefault();\n    try { await loadReservationList(); } catch (error) { showToast(error.message, 'error'); }\n  });\n  $('#clear-filters').addEventListener('click', async () => {\n    $('#reservation-filter').reset();\n    try { await loadReservationList(); } catch (error) { showToast(error.message, 'error'); }\n  });\n  $('#reservations-body').addEventListener('click', (event) => {\n    const button = event.target.closest('[data-action]');\n    if (!button) return;\n    const id = Number(button.dataset.id);\n    const reservation = state.filteredReservations.find((item) => item.id === id) || state.reservations.find((item) => item.id === id);\n    if (!reservation) return;\n    if (button.dataset.action === 'detail') openReservationDetail(reservation);\n    if (button.dataset.action === 'edit') startEditingReservation(reservation);\n    if (button.dataset.action === 'cancel') cancelReservation(id);\n  });\n  $('#export-csv').addEventListener('click', exportReservationsCsv);\n  $('#availability-form').addEventListener('submit', consultAvailability);\n\n  $('#space-form').addEventListener('submit', async (event) => {\n    event.preventDefault();\n    clearFormMessage('#space-form-message');\n    const id = $('#space-id').value;\n    const data = {\n      nombre: $('#space-name').value.trim(),\n      ubicacion: $('#space-location').value.trim(),\n      capacidad: Number($('#space-capacity').value)\n    };\n    try {\n      const result = await api(id ? `/espacios/${id}` : '/espacios', {\n        method: id ? 'PUT' : 'POST', body: JSON.stringify(data)\n      });\n      resetSpaceForm();\n      showToast(result.mensaje || 'Espacio guardado correctamente.');\n      await loadBaseData();\n    } catch (error) {\n      showFormMessage('#space-form-message', error.message, 'error');\n    }\n  });\n  $('#cancel-space-edit').addEventListener('click', resetSpaceForm);\n  $('#spaces-list').addEventListener('click', (event) => {\n    const button = event.target.closest('[data-action=\"edit-space\"]');\n    if (!button) return;\n    const space = state.spaces.find((item) => item.id === Number(button.dataset.id));\n    if (space) editSpace(space);\n  });\n\n  const closeDialog = () => {\n    const dialog = $('#reservation-dialog');\n    if (typeof dialog.close === 'function' && dialog.open) dialog.close();\n    else dialog.removeAttribute('open');\n  };\n  $('#close-dialog').addEventListener('click', closeDialog);\n  $('#dialog-close-bottom').addEventListener('click', closeDialog);\n  $('#reservation-dialog').addEventListener('click', (event) => {\n    if (event.target === $('#reservation-dialog')) closeDialog();\n  });\n}\n\nasync function startApp() {\n  $('#reservation-date').min = localDateString();\n  $('#reservation-date').value = defaultFutureDate();\n  $('#availability-date').value = defaultFutureDate();\n  $('#availability-date').min = localDateString();\n  registerEvents();\n  $('#show-login').addEventListener('click', () => { $('#login-form').hidden = false; $('#register-form').hidden = true; });\n  $('#show-register').addEventListener('click', () => { $('#login-form').hidden = true; $('#register-form').hidden = false; });\n  const authenticate = async (url, payload) => {\n    const result = await api(url, { method: 'POST', body: JSON.stringify(payload) });\n    state.token = result.token; state.user = result.usuario;\n    storage.set('reservaToken', state.token); storage.set('reservaUser', JSON.stringify(state.user));\n    $('#auth-screen').hidden = true; $('#application-shell').hidden = false;\n    $('#current-user-name').textContent = state.user.nombre;\n    $('#current-user-role').textContent = state.user.rol === 'directivo' ? 'Directivo' : state.user.rol === 'docente' ? 'Docente' : 'Alumno';\n    $$('[data-admin-only]').forEach(el => { el.hidden = state.user.rol !== 'directivo'; });\n    $('#reservation-requester').value = state.user.nombre; $('#reservation-requester').readOnly = state.user.rol !== 'directivo';\n    await loadBaseData(); resetReservationForm();\n  };\n  $('#login-form').addEventListener('submit', async e => { e.preventDefault(); try { await authenticate('/usuarios/login', { correo: $('#login-email').value, password: $('#login-password').value }); } catch (err) { showFormMessage('#login-message', err.message); } });\n  $('#register-form').addEventListener('submit', async e => { e.preventDefault(); try { await authenticate('/usuarios/registro', { nombre: $('#register-name').value, correo: $('#register-email').value, password: $('#register-password').value, rol: $('#register-role').value }); } catch (err) { showFormMessage('#register-message', err.message); } });\n  $('#logout-button').addEventListener('click', async () => { try { await api('/usuarios/logout', { method: 'POST' }); } catch {} storage.remove('reservaToken'); storage.remove('reservaUser'); state.token = ''; state.user = null; $('#application-shell').hidden = true; $('#auth-screen').hidden = false; $('#login-form').reset(); });\n  if (state.token && state.user) {\n    try { const me = await api('/usuarios/perfil'); state.user = me; $('#auth-screen').hidden = true; $('#application-shell').hidden = false; $('#current-user-name').textContent = me.nombre; $('#current-user-role').textContent = me.rol; $$('[data-admin-only]').forEach(el => { el.hidden = me.rol !== 'directivo'; }); $('#reservation-requester').value = me.nombre; $('#reservation-requester').readOnly = me.rol !== 'directivo'; await loadBaseData(); }\n    catch { storage.remove('reservaToken'); storage.remove('reservaUser'); state.token = ''; state.user = null; }\n  }\n}\n\ndocument.addEventListener('DOMContentLoaded', startApp);\n",
 "public/index.html": "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#1E4FA3\">\n  <meta name=\"description\" content=\"Prototipo acad\u00e9mico para gestionar reservas de espacios institucionales.\">\n  <title>Reserva de Espacios | Instituci\u00f3n</title>\n  <link rel=\"stylesheet\" href=\"/styles.css\">\n  <script src=\"/app.js\" defer></script>\n</head>\n<body>\n  <section id=\"auth-screen\" class=\"auth-screen\">\n    <div class=\"auth-card\">\n      <p class=\"eyebrow\">PORTAL INSTITUCIONAL</p><h1>Reserva de espacios acad\u00e9micos</h1>\n      <p>Inicia sesi\u00f3n o crea tu cuenta para gestionar tus reservas.</p>\n      <div class=\"auth-tabs\"><button type=\"button\" id=\"show-login\" class=\"button button-primary\">Iniciar sesi\u00f3n</button><button type=\"button\" id=\"show-register\" class=\"button button-secondary\">Crear cuenta</button></div>\n      <form id=\"login-form\" class=\"auth-form\">\n        <label>Correo institucional<input type=\"email\" id=\"login-email\" required autocomplete=\"username\" placeholder=\"correo@institucion.edu\"></label>\n        <label>Contrase\u00f1a<input type=\"password\" id=\"login-password\" required autocomplete=\"current-password\" placeholder=\"M\u00ednimo 8 caracteres\"></label>\n        <div id=\"login-message\" class=\"form-message\" role=\"alert\" hidden></div><button class=\"button button-primary\" type=\"submit\">Entrar</button>\n      </form>\n      <form id=\"register-form\" class=\"auth-form\" hidden>\n        <label>Nombre completo<input type=\"text\" id=\"register-name\" minlength=\"3\" maxlength=\"100\" required autocomplete=\"name\"></label>\n        <label>Correo institucional<input type=\"email\" id=\"register-email\" required autocomplete=\"email\"></label>\n        <label>Perfil<select id=\"register-role\" required><option value=\"alumno\">Alumno / estudiante</option><option value=\"docente\">Docente</option></select><small>El perfil directivo solo puede ser asignado por un administrador del sistema.</small></label>\n        <label>Contrase\u00f1a<input type=\"password\" id=\"register-password\" minlength=\"8\" required autocomplete=\"new-password\"></label>\n        <div id=\"register-message\" class=\"form-message\" role=\"alert\" hidden></div><button class=\"button button-primary\" type=\"submit\">Crear cuenta</button>\n      </form>\n      <p class=\"auth-demo\"><strong>Cuenta directiva de demostraci\u00f3n</strong><br>directivo@institucion.edu<br>Contrase\u00f1a: Admin123!<br><small>C\u00e1mbiala antes de cualquier uso real.</small></p>\n    </div>\n  </section>\n  <div class=\"app-shell\" id=\"application-shell\" hidden>\n    <aside class=\"sidebar\" aria-label=\"Navegaci\u00f3n principal\">\n      <a class=\"brand\" href=\"#inicio\" data-view-link=\"dashboard\" aria-label=\"Ir al inicio\">\n        <span class=\"brand-mark\" aria-hidden=\"true\">\u2302</span>\n        <span><strong>Reserva de Espacios</strong><small>Portal institucional</small></span>\n      </a>\n      <div class=\"nav-label\">MEN\u00da PRINCIPAL</div>\n      <nav class=\"main-nav\">\n        <button class=\"nav-link active\" type=\"button\" data-view-link=\"dashboard\"><span aria-hidden=\"true\">\u25a6</span> Resumen</button>\n        <button class=\"nav-link\" type=\"button\" data-view-link=\"form\"><span aria-hidden=\"true\">\uff0b</span> Nueva reserva</button>\n        <button class=\"nav-link\" type=\"button\" data-view-link=\"reservas\"><span aria-hidden=\"true\">\u25a4</span> Reservas</button>\n        <button class=\"nav-link\" type=\"button\" data-view-link=\"disponibilidad\"><span aria-hidden=\"true\">\u25f7</span> Disponibilidad</button>\n        <button class=\"nav-link\" type=\"button\" data-view-link=\"espacios\" data-admin-only><span aria-hidden=\"true\">\u2302</span> Espacios</button>\n        <button class=\"nav-link\" type=\"button\" data-view-link=\"perfiles\" data-admin-only><span aria-hidden=\"true\">\u2659</span> Perfiles</button>\n      </nav>\n      <div class=\"sidebar-note\">\n        <span class=\"note-icon\" aria-hidden=\"true\">i</span>\n        <p><strong>Prototipo acad\u00e9mico</strong><br>La informaci\u00f3n se conserva solo mientras el servidor est\u00e9 encendido.</p>\n      </div>\n      <div class=\"sidebar-footer\">Caso 2 \u00b7 Programaci\u00f3n Aplicada</div>\n    </aside>\n\n    <main class=\"main-content\">\n      <header class=\"topbar\">\n        <div>\n          <p class=\"eyebrow\">GESTI\u00d3N DE ESPACIOS ACAD\u00c9MICOS</p>\n          <h1 id=\"page-title\">Resumen general</h1>\n        </div>\n        <div class=\"topbar-user\"><span class=\"user-avatar\" aria-hidden=\"true\">U</span><span><strong id=\"current-user-name\">Usuario</strong><small id=\"current-user-role\">Perfil</small></span><button class=\"button button-secondary button-small\" id=\"logout-button\" type=\"button\">Salir</button></div>\n      </header>\n\n      <div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\" hidden></div>\n\n      <section class=\"view\" id=\"view-dashboard\">\n        <div class=\"welcome-row\">\n          <div><h2>Panel de reservas</h2><p>Consulta los espacios y organiza las pr\u00f3ximas actividades acad\u00e9micas.</p></div>\n          <button class=\"button button-primary\" type=\"button\" data-go=\"form\">\uff0b Crear reserva</button>\n        </div>\n        <div class=\"stats-grid\">\n          <article class=\"stat-card\"><div class=\"stat-icon blue\" aria-hidden=\"true\">\u25a4</div><div><p>Total de reservas</p><strong id=\"stat-total\">0</strong><small>Registradas en memoria</small></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon green\" aria-hidden=\"true\">\u2713</div><div><p>Reservas activas</p><strong id=\"stat-active\">0</strong><small>Sin cancelar ni finalizar</small></div></article>\n          <article class=\"stat-card\"><div class=\"stat-icon amber\" aria-hidden=\"true\">\u2302</div><div><p>Espacios disponibles</p><strong id=\"stat-spaces\">0</strong><small>Espacios registrados</small></div></article>\n        </div>\n        <div class=\"panel\">\n          <div class=\"panel-heading\"><div><h2>Pr\u00f3ximas reservas</h2><p>Las reservas se ordenan por fecha y hora.</p></div><button class=\"button button-secondary button-small\" type=\"button\" data-go=\"reservas\">Ver todas</button></div>\n          <div class=\"table-wrap\"><table><thead><tr><th>Espacio</th><th>Solicitante</th><th>Fecha</th><th>Horario</th><th>Estado</th></tr></thead><tbody id=\"upcoming-body\"><tr><td colspan=\"5\" class=\"empty-cell\">Todav\u00eda no hay reservas. Crea la primera con el bot\u00f3n \u201cCrear reserva\u201d.</td></tr></tbody></table></div>\n        </div>\n        <div class=\"info-strip\"><span aria-hidden=\"true\">\u2726</span><div><strong>Regla principal</strong><p>El sistema rechaza una reserva si el mismo espacio ya est\u00e1 ocupado en la misma fecha y el horario se cruza. Los horarios consecutivos s\u00ed est\u00e1n permitidos.</p></div></div>\n      </section>\n\n      <section class=\"view\" id=\"view-form\" hidden>\n        <div class=\"section-intro\"><span class=\"section-icon\" aria-hidden=\"true\">\uff0b</span><div><h2 id=\"reservation-form-title\">Registrar una reserva</h2><p>Completa los datos obligatorios para solicitar un espacio acad\u00e9mico.</p></div></div>\n        <div class=\"panel form-panel\">\n          <form id=\"reservation-form\">\n            <input type=\"hidden\" id=\"reservation-id\">\n            <div class=\"form-grid\">\n              <label>Espacio acad\u00e9mico <span class=\"required\">*</span><select id=\"reservation-space\" required><option value=\"\">Selecciona un espacio</option></select><small>El espacio debe existir en el listado institucional.</small></label>\n              <label>Nombre del solicitante <span class=\"required\">*</span><input id=\"reservation-requester\" type=\"text\" minlength=\"3\" maxlength=\"100\" placeholder=\"Ej. Ana P\u00e9rez\" required><small>Escribe el nombre de quien solicita la reserva.</small></label>\n              <label>Fecha <span class=\"required\">*</span><input id=\"reservation-date\" type=\"date\" required><small>No se permiten fechas anteriores a hoy.</small></label>\n              <div class=\"field-pair\"><label>Hora de inicio <span class=\"required\">*</span><input id=\"reservation-start\" type=\"time\" required></label><label>Hora de fin <span class=\"required\">*</span><input id=\"reservation-end\" type=\"time\" required></label></div>\n              <label class=\"full-width\">Motivo de la reserva <span class=\"muted\">(opcional)</span><textarea id=\"reservation-reason\" rows=\"3\" maxlength=\"300\" placeholder=\"Ej. Trabajo grupal, tutor\u00eda o pr\u00e1ctica de laboratorio\"></textarea><small>M\u00e1ximo 300 caracteres.</small></label>\n            </div>\n            <div class=\"form-message\" id=\"reservation-form-message\" role=\"alert\" hidden></div>\n            <div class=\"form-actions\"><button class=\"button button-secondary\" id=\"cancel-edit\" type=\"button\" hidden>Descartar cambios</button><button class=\"button button-primary\" type=\"submit\" id=\"reservation-submit\">Confirmar reserva</button></div>\n          </form>\n        </div>\n        <div class=\"info-strip\"><span aria-hidden=\"true\">i</span><div><strong>Antes de confirmar</strong><p>Verifica que la hora final sea posterior a la hora inicial. El servidor revisar\u00e1 si el espacio ya tiene otra reserva activa en ese horario.</p></div></div>\n      </section>\n\n      <section class=\"view\" id=\"view-reservas\" hidden>\n        <div class=\"section-intro\"><span class=\"section-icon\" aria-hidden=\"true\">\u25a4</span><div><h2>Reservas registradas</h2><p>Consulta, filtra, edita o cancela las reservas de este prototipo.</p></div></div>\n        <div class=\"panel filter-panel\"><form id=\"reservation-filter\" class=\"filter-grid\">\n          <label>Espacio<select id=\"filter-space\"><option value=\"\">Todos los espacios</option></select></label>\n          <label>Solicitante<input id=\"filter-requester\" type=\"search\" placeholder=\"Buscar por nombre\"></label>\n          <label>Estado<select id=\"filter-status\"><option value=\"\">Todos los estados</option><option value=\"activa\">Activa</option><option value=\"finalizada\">Finalizada</option><option value=\"cancelada\">Cancelada</option></select></label>\n          <label>Fecha<input id=\"filter-date\" type=\"date\"></label>\n          <div class=\"filter-actions\"><button class=\"button button-primary button-small\" type=\"submit\">Aplicar filtros</button><button class=\"button button-secondary button-small\" id=\"clear-filters\" type=\"button\">Limpiar</button></div>\n        </form></div>\n        <div class=\"panel\"><div class=\"panel-heading\"><div><h2>Listado de reservas</h2><p id=\"reservation-count\">0 resultados</p></div><button class=\"button button-secondary button-small\" id=\"export-csv\" type=\"button\">\u2193 Exportar CSV</button></div>\n          <div class=\"table-wrap\"><table><thead><tr><th>ID</th><th>Espacio</th><th>Solicitante</th><th>Fecha</th><th>Horario</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id=\"reservations-body\"><tr><td colspan=\"7\" class=\"empty-cell\">Cargando reservas\u2026</td></tr></tbody></table></div>\n        </div>\n      </section>\n\n      <section class=\"view\" id=\"view-disponibilidad\" hidden>\n        <div class=\"section-intro\"><span class=\"section-icon\" aria-hidden=\"true\">\u25f7</span><div><h2>Disponibilidad de espacios</h2><p>Consulta las reservas activas de un espacio en la fecha seleccionada.</p></div></div>\n        <div class=\"panel\"><form id=\"availability-form\" class=\"availability-form\"><label>Espacio acad\u00e9mico<select id=\"availability-space\" required><option value=\"\">Selecciona un espacio</option></select></label><label>Fecha<input id=\"availability-date\" type=\"date\" required></label><button class=\"button button-primary\" type=\"submit\">Consultar disponibilidad</button></form></div>\n        <div id=\"availability-result\" class=\"panel availability-result\"><div class=\"empty-state\"><span aria-hidden=\"true\">\u25f7</span><h3>Consulta un espacio</h3><p>Selecciona un espacio y una fecha para ver los horarios registrados.</p></div></div>\n      </section>\n\n      <section class=\"view\" id=\"view-espacios\" hidden>\n        <div class=\"section-intro\"><span class=\"section-icon\" aria-hidden=\"true\">\u2302</span><div><h2>Espacios acad\u00e9micos</h2><p>Listado y edici\u00f3n de salas y laboratorios (solo directivos).</p></div></div>\n        <div class=\"two-column-layout\">\n          <div class=\"panel\"><div class=\"panel-heading\"><div><h2>Espacios registrados</h2><p>Los nombres se utilizan en los formularios de reserva.</p></div></div><div id=\"spaces-list\" class=\"space-list\"></div></div>\n          <div class=\"panel\"><div class=\"panel-heading\"><div><h2 id=\"space-form-title\">Agregar espacio</h2><p>Nombre, ubicaci\u00f3n y capacidad son obligatorios.</p></div></div>\n            <form id=\"space-form\" class=\"space-form\"><input id=\"space-id\" type=\"hidden\"><label>Nombre del espacio<input id=\"space-name\" type=\"text\" minlength=\"3\" maxlength=\"100\" placeholder=\"Ej. Sala de estudio 2\" required></label><label>Ubicaci\u00f3n<input id=\"space-location\" type=\"text\" maxlength=\"100\" placeholder=\"Ej. Bloque A, segundo piso\" required></label><label>Capacidad<input id=\"space-capacity\" type=\"number\" min=\"1\" step=\"1\" placeholder=\"Ej. 8\" required></label><div class=\"form-message\" id=\"space-form-message\" role=\"alert\" hidden></div><div class=\"form-actions\"><button class=\"button button-secondary\" id=\"cancel-space-edit\" type=\"button\" hidden>Descartar cambios</button><button class=\"button button-primary\" id=\"space-submit\" type=\"submit\">Guardar espacio</button></div></form>\n          </div>\n        </div>\n        <div class=\"warning-strip\"><strong>Acceso restringido:</strong> solo los directivos pueden crear o editar espacios. El servidor lo verifica en cada solicitud.</div>\n      </section>\n\n      <section class=\"view\" id=\"view-perfiles\" hidden data-admin-only>\n        <div class=\"section-intro\"><span class=\"section-icon\" aria-hidden=\"true\">\u2659</span><div><h2>Perfiles registrados</h2><p>Informaci\u00f3n de las cuentas registradas en el sistema.</p></div></div>\n        <div class=\"panel\"><div class=\"table-wrap\"><table><thead><tr><th>ID</th><th>Nombre</th><th>Correo</th><th>Perfil</th></tr></thead><tbody id=\"profiles-body\"><tr><td colspan=\"4\">Cargando perfiles\u2026</td></tr></tbody></table></div></div>\n      </section>\n      <footer class=\"main-footer\"><span>Reserva de Espacios Acad\u00e9micos</span><span>Proyecto integrador \u00b7 Caso 2</span></footer>\n    </main>\n  </div>\n\n  <dialog id=\"reservation-dialog\" class=\"detail-dialog\">\n    <div class=\"dialog-header\"><div><p class=\"eyebrow\">DETALLE</p><h2 id=\"dialog-title\">Reserva</h2></div><button class=\"icon-button\" id=\"close-dialog\" type=\"button\" aria-label=\"Cerrar detalle\">\u00d7</button></div>\n    <div id=\"dialog-content\" class=\"detail-content\"></div>\n    <div class=\"form-actions\"><button class=\"button button-secondary\" id=\"dialog-close-bottom\" type=\"button\">Cerrar</button></div>\n  </dialog>\n  <noscript>Esta aplicaci\u00f3n necesita JavaScript activado en el navegador.</noscript>\n</body>\n</html>\n",
 "tests/validaciones.test.js": "const test = require('node:test');\nconst assert = require('node:assert/strict');\nconst {\n  esFechaISOValida,\n  esHoraValida,\n  hayCruceHorario\n} = require('../src/utils/validaciones');\n\ntest('acepta fechas reales en formato AAAA-MM-DD', () => {\n  assert.equal(esFechaISOValida('2026-10-19'), true);\n  assert.equal(esFechaISOValida('2026-02-30'), false);\n  assert.equal(esFechaISOValida('19-10-2026'), false);\n});\n\ntest('valida horas en formato de 24 horas', () => {\n  assert.equal(esHoraValida('08:00'), true);\n  assert.equal(esHoraValida('23:59'), true);\n  assert.equal(esHoraValida('25:10'), false);\n  assert.equal(esHoraValida('8:00'), false);\n});\n\ntest('detecta cruces y permite reservas consecutivas', () => {\n  const existentes = [{ id: 1, espacio: 2, fecha: '2026-12-01', horaInicio: '08:00', horaFin: '10:00', estado: 'activa' }];\n  const cruzada = { espacio: 2, fecha: '2026-12-01', horaInicio: '09:00', horaFin: '11:00' };\n  const consecutiva = { espacio: 2, fecha: '2026-12-01', horaInicio: '10:00', horaFin: '12:00' };\n  const otroEspacio = { espacio: 3, fecha: '2026-12-01', horaInicio: '09:00', horaFin: '11:00' };\n\n  assert.equal(hayCruceHorario(cruzada, existentes)?.id, 1);\n  assert.equal(hayCruceHorario(consecutiva, existentes), null);\n  assert.equal(hayCruceHorario(otroEspacio, existentes), null);\n  assert.equal(hayCruceHorario(cruzada, [{ ...existentes[0], estado: 'cancelada' }]), null);\n});\n\ntest('al editar, ignora la misma reserva al comparar horarios', () => {\n  const existentes = [{ id: 7, espacio: 2, fecha: '2026-12-01', horaInicio: '08:00', horaFin: '10:00', estado: 'activa' }];\n  const misma = { espacio: 2, fecha: '2026-12-01', horaInicio: '09:00', horaFin: '11:00' };\n  assert.equal(hayCruceHorario(misma, existentes, 7), null);\n});\n",
 "tests/reservasController.test.js": "const test = require('node:test');\nconst assert = require('node:assert/strict');\nconst controller = require('../src/controllers/reservasController');\nconst { fechaActualBogota } = require('../src/utils/validaciones');\n\nfunction fechaFutura(dias) {\n  const [anio, mes, dia] = fechaActualBogota().split('-').map(Number);\n  const fecha = new Date(Date.UTC(anio, mes - 1, dia + dias));\n  return `${fecha.getUTCFullYear()}-${String(fecha.getUTCMonth() + 1).padStart(2, '0')}-${String(fecha.getUTCDate()).padStart(2, '0')}`;\n}\n\nfunction llamarControlador(controlador, req) {\n  const res = {\n    statusCode: 200,\n    body: null,\n    status(codigo) { this.statusCode = codigo; return this; },\n    json(cuerpo) { this.body = cuerpo; return this; }\n  };\n  controlador(req, res);\n  return res;\n}\n\ntest('flujo de reservas: crear, rechazar cruces, editar, consultar y cancelar', () => {\n  const fecha = fechaFutura(3);\n  const datos = {\n    espacio: 1,\n    solicitante: 'Ana P\u00e9rez',\n    fecha,\n    horaInicio: '08:00',\n    horaFin: '10:00',\n    motivo: 'Trabajo grupal'\n  };\n\n  let respuesta = llamarControlador(controller.crear, { body: datos });\n  assert.equal(respuesta.statusCode, 201);\n  assert.equal(respuesta.body.reserva.estado, 'activa');\n  const idPrimera = respuesta.body.reserva.id;\n\n  respuesta = llamarControlador(controller.crear, { body: { ...datos, solicitante: 'Luis Mora', horaInicio: '09:00', horaFin: '11:00' } });\n  assert.equal(respuesta.statusCode, 409, 'rechaza intervalos que se cruzan');\n\n  respuesta = llamarControlador(controller.crear, { body: { ...datos, solicitante: 'Luis Mora', horaInicio: '10:00', horaFin: '12:00' } });\n  assert.equal(respuesta.statusCode, 201, 'permite horarios consecutivos');\n\n  respuesta = llamarControlador(controller.editar, { params: { id: String(idPrimera) }, body: { ...datos, horaInicio: '07:00', horaFin: '08:00' } });\n  assert.equal(respuesta.statusCode, 200, 'la edici\u00f3n ignora la propia reserva al validar cruces');\n\n  respuesta = llamarControlador(controller.consultarDisponibilidad, { query: { espacio: '1', fecha } });\n  assert.equal(respuesta.statusCode, 200);\n  assert.equal(respuesta.body.totalReservasActivas, 2);\n\n  respuesta = llamarControlador(controller.cancelar, { params: { id: String(idPrimera) } });\n  assert.equal(respuesta.statusCode, 200);\n  assert.equal(respuesta.body.reserva.estado, 'cancelada');\n\n  respuesta = llamarControlador(controller.crear, { body: { ...datos, solicitante: 'Mar\u00eda Sol', horaInicio: '07:30', horaFin: '08:30' } });\n  assert.equal(respuesta.statusCode, 201, 'la reserva cancelada ya no bloquea su antiguo horario');\n\n  respuesta = llamarControlador(controller.listar, { query: {} });\n  assert.equal(respuesta.body.length, 3, 'la cancelada se conserva en el listado');\n});\n",
 "tests/cruces.test.js": "// Tabla de casos de la secci\u00f3n 4.4 del documento del proyecto (regla para evitar cruces).\nconst test = require('node:test');\nconst assert = require('node:assert/strict');\nconst { hayCruceHorario } = require('../src/utils/validaciones');\n\nconst existente = [{ id: 1, espacio: 1, fecha: '2030-01-10', horaInicio: '08:00', horaFin: '10:00', estado: 'activa' }];\nconst casos = [\n  ['10:00', '12:00', false],\n  ['09:00', '11:00', true],\n  ['08:30', '09:30', true],\n  ['07:00', '08:00', false],\n  ['10:00', '11:00', false]\n];\n\nfor (const [horaInicio, horaFin, rechazada] of casos) {\n  test(`08:00\u201310:00 frente a ${horaInicio}\u2013${horaFin}: ${rechazada ? 'rechazada' : 'permitida'}`, () => {\n    const nueva = { espacio: 1, fecha: '2030-01-10', horaInicio, horaFin };\n    assert.equal(Boolean(hayCruceHorario(nueva, existente)), rechazada);\n  });\n}\n",
 "tests/api.test.js": "// Pruebas de integraci\u00f3n: levantan el servidor en un puerto libre y llaman a la API real.\nconst test = require('node:test');\nconst assert = require('node:assert/strict');\nconst app = require('../index');\nconst { fechaActualBogota } = require('../src/utils/validaciones');\n\nlet servidor;\nlet base;\n\nfunction fechaFutura(dias) {\n  const [a, m, d] = fechaActualBogota().split('-').map(Number);\n  const f = new Date(Date.UTC(a, m - 1, d + dias));\n  return f.toISOString().slice(0, 10);\n}\n\nasync function pedir(ruta, { metodo = 'GET', cuerpo, token } = {}) {\n  const respuesta = await fetch(base + ruta, {\n    method: metodo,\n    headers: {\n      ...(cuerpo ? { 'Content-Type': 'application/json' } : {}),\n      ...(token ? { Authorization: `Bearer ${token}` } : {})\n    },\n    body: cuerpo ? JSON.stringify(cuerpo) : undefined\n  });\n  return { estado: respuesta.status, datos: await respuesta.json() };\n}\n\ntest.before(() => new Promise((resolve) => {\n  servidor = app.listen(0, () => {\n    base = `http://127.0.0.1:${servidor.address().port}`;\n    resolve();\n  });\n}));\ntest.after(() => new Promise((resolve) => servidor.close(resolve)));\n\ntest('las rutas protegidas exigen sesi\u00f3n (401)', async () => {\n  assert.equal((await pedir('/reservas')).estado, 401);\n  assert.equal((await pedir('/espacios')).estado, 401);\n});\n\ntest('no se puede registrar un directivo ni usar contrase\u00f1as cortas', async () => {\n  const base1 = { nombre: 'Persona Prueba', correo: 'x@u.edu', password: 'clave12345', rol: 'directivo' };\n  assert.equal((await pedir('/usuarios/registro', { metodo: 'POST', cuerpo: base1 })).estado, 400);\n  assert.equal((await pedir('/usuarios/registro', { metodo: 'POST', cuerpo: { ...base1, rol: 'alumno', password: '123' } })).estado, 400);\n});\n\ntest('flujo completo con permisos por perfil', async () => {\n  const fecha = fechaFutura(5);\n  const reg = (nombre, correo, rol) => pedir('/usuarios/registro', { metodo: 'POST', cuerpo: { nombre, correo, password: 'clave12345', rol } });\n\n  const ana = (await reg('Ana P\u00e9rez', 'ana@u.edu', 'alumno')).datos;\n  const luis = (await reg('Luis Mora', 'luis@u.edu', 'docente')).datos;\n  assert.ok(ana.token && luis.token);\n  assert.equal((await reg('Otra Ana', 'ana@u.edu', 'alumno')).estado, 409, 'correo repetido');\n\n  const login = await pedir('/usuarios/login', { metodo: 'POST', cuerpo: { correo: 'directivo@institucion.edu', password: 'Admin123!' } });\n  assert.equal(login.estado, 200);\n  const dir = login.datos.token;\n  assert.equal((await pedir('/usuarios/login', { metodo: 'POST', cuerpo: { correo: 'ana@u.edu', password: 'mala' } })).estado, 401);\n\n  const datos = { espacio: 1, fecha, horaInicio: '08:00', horaFin: '10:00', motivo: 'Estudio' };\n  const creada = await pedir('/reservas', { metodo: 'POST', cuerpo: datos, token: ana.token });\n  assert.equal(creada.estado, 201);\n  assert.equal(creada.datos.reserva.solicitante, 'Ana P\u00e9rez', 'el solicitante sale de la sesi\u00f3n');\n  const id = creada.datos.reserva.id;\n\n  const cruce = await pedir('/reservas', { metodo: 'POST', cuerpo: { ...datos, horaInicio: '09:00', horaFin: '11:00' }, token: luis.token });\n  assert.equal(cruce.estado, 409);\n  assert.equal((await pedir('/reservas', { metodo: 'POST', cuerpo: { ...datos, horaInicio: '10:00', horaFin: '12:00' }, token: luis.token })).estado, 201);\n\n  // Luis no puede ver ni tocar la reserva de Ana; el directivo s\u00ed.\n  assert.equal((await pedir(`/reservas/${id}`, { token: luis.token })).estado, 403);\n  assert.equal((await pedir(`/reservas/${id}`, { metodo: 'DELETE', token: luis.token })).estado, 403);\n  const propias = await pedir('/reservas', { token: luis.token });\n  assert.equal(propias.datos.length, 1);\n  assert.equal((await pedir('/reservas', { token: dir })).datos.length, 2);\n\n  const disp = await pedir(`/reservas/disponibilidad?espacio=1&fecha=${fecha}`, { token: luis.token });\n  assert.equal(disp.datos.totalReservasActivas, 2);\n\n  assert.equal((await pedir(`/reservas/${id}`, { metodo: 'PUT', cuerpo: { horaInicio: '07:00', horaFin: '08:00' }, token: ana.token })).estado, 200);\n  assert.equal((await pedir(`/reservas/${id}`, { metodo: 'DELETE', token: ana.token })).datos.reserva.estado, 'cancelada');\n\n  // Espacios y usuarios: solo directivo.\n  assert.equal((await pedir('/espacios', { metodo: 'POST', cuerpo: { nombre: 'Aula nueva', ubicacion: 'Bloque D', capacidad: 20 }, token: ana.token })).estado, 403);\n  assert.equal((await pedir('/espacios', { metodo: 'POST', cuerpo: { nombre: 'Aula nueva', ubicacion: 'Bloque D', capacidad: 20 }, token: dir })).estado, 201);\n  assert.equal((await pedir('/usuarios', { token: ana.token })).estado, 403);\n  assert.equal((await pedir('/usuarios', { token: dir })).estado, 200);\n\n  assert.equal((await pedir('/usuarios/logout', { metodo: 'POST', token: ana.token })).estado, 200);\n  assert.equal((await pedir('/reservas', { token: ana.token })).estado, 401, 'el token cerrado ya no sirve');\n});\n\ntest('rechaza reservas con hora de inicio ya pasada el mismo d\u00eda', async () => {\n  const dir = (await pedir('/usuarios/login', { metodo: 'POST', cuerpo: { correo: 'directivo@institucion.edu', password: 'Admin123!' } })).datos.token;\n  const r = await pedir('/reservas', { metodo: 'POST', cuerpo: { espacio: 1, fecha: fechaActualBogota(), horaInicio: '00:00', horaFin: '00:01' }, token: dir });\n  assert.equal(r.estado, 400);\n});\n"
};
let total = 0;
for (const [ruta, contenido] of Object.entries(archivos)) {
  const destino = path.join(process.cwd(), ruta);
  fs.mkdirSync(path.dirname(destino), { recursive: true });
  fs.writeFileSync(destino, contenido, 'utf8');
  total++;
}
console.log('Listo: se crearon ' + total + ' archivos.');
console.log('Ahora ejecuta: npm install && npm start');